INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0735', 'Sit-Up v. 2', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3679', 'Sit-Up With Arms On Chest', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Cross your arms over your chest.","Engaging your abs, lift your upper body off the ground towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपनी बाहों को अपनी छाती के ऊपर से क्रॉस करें।","अपने पेट को शामिल करते हुए, अपने ऊपरी शरीर को अपने घुटनों की ओर जमीन से ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3361', 'Skater Hops', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","glutes","calves"]', 'body weight', 'cardio', NULL, '["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump to the right, landing on your right foot.","As you land, swing your left leg behind your right leg and tap the ground with your left toes.","Immediately jump to the left, landing on your left foot.","As you land, swing your right leg behind your left leg and tap the ground with your right toes.","Continue alternating sides, jumping and tapping the ground with each leg.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को थोड़ा मोड़ें और अपने दाहिने पैर पर उतरते हुए दाईं ओर कूदें।","जैसे ही आप उतरें, अपने बाएं पैर को अपने दाहिने पैर के पीछे झुकाएं और अपने बाएं पैर की उंगलियों से जमीन को थपथपाएं।","अपने बाएं पैर पर उतरते हुए तुरंत बाईं ओर कूदें।","जैसे ही आप उतरें, अपने दाहिने पैर को अपने बाएं पैर के पीछे झुकाएं और अपने दाहिने पैर की उंगलियों से जमीन को थपथपाएं।","बारी-बारी से करवट बदलना जारी रखें, कूदें और प्रत्येक पैर से ज़मीन को थपथपाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-2142', 'Ski Ergometer', 'upper arms', 'triceps', '["shoulders","forearms"]', 'skierg machine', 'strength', NULL, '["Adjust the seat height and footrests to a comfortable position.","Grasp the handles with an overhand grip, palms facing down.","Sit up straight with your feet flat on the footrests.","Extend your arms straight out in front of you, keeping your elbows slightly bent.","Engage your triceps and push the handles down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई और फुटरेस्ट को आरामदायक स्थिति में समायोजित करें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपने पैरों को फुटरेस्ट पर सपाट करके सीधे बैठें।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, अपनी भुजाओं को अपने सामने सीधा फैलाएँ।","अपने ट्राइसेप्स को संलग्न करें और हैंडल को अपनी जांघों की ओर नीचे धकेलें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3671', 'Ski Step', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","glutes","calves"]', 'body weight', 'cardio', NULL, '["Stand with your feet shoulder-width apart.","Bend your knees slightly and keep your back straight.","Jump to the right, landing on your right foot while swinging your left leg behind your right leg.","Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.","Continue alternating jumps from side to side, mimicking a skiing motion.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ सीधी रखें।","अपने दाहिने पैर के पीछे अपने बाएं पैर को घुमाते हुए अपने दाहिने पैर पर उतरते हुए दाईं ओर कूदें।","तुरंत बाईं ओर कूदें, अपने बाएं पैर पर उतरें और अपने दाहिने पैर को अपने बाएं पैर के पीछे घुमाएँ।","स्कीइंग गति की नकल करते हुए, अगल-बगल से बारी-बारी से छलांग लगाना जारी रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-3304', 'Skin The Cat', 'back', 'upper back', '["shoulders","core"]', 'body weight', 'strength', NULL, '["Start by hanging from a bar with your arms fully extended and your body relaxed.","Engage your core and lift your legs up, bringing your knees towards your chest.","Continue to lift your legs up and over your head, allowing your body to pass through the arms.","Once your legs are fully extended over your head, begin to lower them back down towards the starting position.","As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को आराम से रखते हुए एक बार से लटककर शुरुआत करें।","अपने कोर को संलग्न करें और अपने पैरों को ऊपर उठाएं, अपने घुटनों को अपनी छाती की ओर लाएं।","अपने पैरों को ऊपर और अपने सिर के ऊपर उठाना जारी रखें, जिससे आपके शरीर को बाहों से गुज़रने की अनुमति मिल सके।","एक बार जब आपके पैर पूरी तरह से आपके सिर के ऊपर फैल जाएं, तो उन्हें वापस प्रारंभिक स्थिति में नीचे लाना शुरू करें।","जैसे ही आप अपने पैरों को नीचे करते हैं, अपने शरीर को बाहों के माध्यम से वापस जाने दें जब तक कि आप अपनी बाहों को फिर से पूरी तरह से फैलाकर लटक न जाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1425', 'Sled 45 Degrees One Leg Press', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'sled machine', 'strength', NULL, '["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the footplate.","Place one foot on the footplate and extend your leg, pushing the sled away from you.","Slowly bend your knee and lower the sled back to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["स्लेज मशीन को 45 डिग्री के कोण पर समायोजित करें।","स्लेज मशीन पर अपनी पीठ पैड से सटाकर और अपने पैरों को फ़ुटप्लेट पर रखकर बैठें।","एक पैर को फ़ुटप्लेट पर रखें और स्लेज को अपने से दूर धकेलते हुए अपने पैर को फैलाएँ।","धीरे-धीरे अपने घुटने को मोड़ें और स्लेज को वापस प्रारंभिक स्थिति में ले आएं।","दूसरे पैर से दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0738', 'Sled 45в° Calf Press', 'lower legs', 'calves', '["hamstrings"]', 'sled machine', 'strength', NULL, '["Adjust the sled machine to a 45-degree angle.","Place your feet on the sled platform with your toes pointing forward.","Push the sled platform away from you by extending your ankles and calves.","Pause for a moment at the top, then slowly lower the sled platform back to the starting position.","Repeat for the desired number of repetitions."]', '["स्लेज मशीन को 45 डिग्री के कोण पर समायोजित करें।","अपने पैरों को स्लेज प्लेटफॉर्म पर इस प्रकार रखें कि आपके पैर की उंगलियां आगे की ओर हों।","अपनी एड़ियों और पिंडलियों को फैलाकर स्लेज प्लेटफॉर्म को अपने से दूर धकेलें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे स्लेज प्लेटफ़ॉर्म को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0739', 'Sled 45в° Leg Press', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'sled machine', 'strength', NULL, '["Adjust the seat and footplate of the sled machine to a comfortable position.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Continue pushing until your legs are almost fully extended, but without locking your knees.","Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.","Repeat for the desired number of repetitions."]', '["स्लेज मशीन की सीट और फ़ुटप्लेट को आरामदायक स्थिति में समायोजित करें।","स्लेज मशीन पर अपनी पीठ बैकरेस्ट से सटाकर और अपने पैरों को फ़ुटप्लेट पर कंधे की चौड़ाई से अलग करके बैठें।","स्थिरता के लिए सीट के किनारों पर हैंडल पकड़ें।","अपने पैरों को फैलाकर, अपनी एड़ियों को फ़ुटप्लेट पर रखते हुए फ़ुटप्लेट को अपने शरीर से दूर धकेलें।","तब तक जोर लगाना जारी रखें जब तक कि आपके पैर लगभग पूरी तरह से विस्तारित न हो जाएं, लेकिन अपने घुटनों को लॉक किए बिना।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने घुटनों को मोड़कर फ़ुटप्लेट को वापस अपने शरीर की ओर नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1464', 'Sled 45в° Leg Press (Back Pov)', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'sled machine', 'strength', NULL, '["Adjust the seat of the sled machine so that your knees are at a 45-degree angle.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards your body, controlling the movement.","Repeat for the desired number of repetitions."]', '["स्लेज मशीन की सीट को इस प्रकार समायोजित करें कि आपके घुटने 45 डिग्री के कोण पर हों।","स्लेज मशीन पर अपनी पीठ बैकरेस्ट से सटाकर और अपने पैरों को फ़ुटप्लेट पर कंधे की चौड़ाई से अलग करके बैठें।","स्थिरता के लिए सीट के किनारों पर हैंडल पकड़ें।","अपने पैरों को फैलाकर, अपनी एड़ियों को फ़ुटप्लेट पर रखते हुए फ़ुटप्लेट को अपने शरीर से दूर धकेलें।","पूरी तरह विस्तारित स्थिति में एक पल के लिए रुकें।","धीरे-धीरे अपने घुटनों को मोड़ें और गति को नियंत्रित करते हुए फ़ुटप्लेट को वापस अपने शरीर की ओर नीचे करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1463', 'Sled 45° Leg Press (Side Pov)', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'sled machine', 'strength', NULL, '["Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push against the footplate to extend your legs, straightening them completely.","Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.","Repeat for the desired number of repetitions."]', '["स्लेज मशीन की सीट को समायोजित करें ताकि जब आपके पैर फ़ुटप्लेट पर हों तो आपके घुटने 90 डिग्री के कोण पर हों।","स्लेज मशीन पर अपनी पीठ बैकरेस्ट के सामने सपाट करके और अपने पैरों को फ़ुटप्लेट पर कंधे की चौड़ाई से अलग करके बैठें।","स्थिरता के लिए सीट के किनारों पर हैंडल पकड़ें।","अपने पैरों को पूरी तरह से सीधा करते हुए, उन्हें फैलाने के लिए फ़ुटप्लेट पर दबाव डालें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने घुटनों को मोड़कर फ़ुटप्लेट को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0740', 'Sled 45в° Leg Wide Press', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'sled machine', 'strength', NULL, '["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the foot platform.","Position your feet wider than shoulder-width apart.","Push against the foot platform to extend your legs and straighten your knees.","Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.","Repeat for the desired number of repetitions."]', '["स्लेज मशीन को 45 डिग्री के कोण पर समायोजित करें।","स्लेज मशीन पर अपनी पीठ पैड से सटाकर और अपने पैरों को फुट प्लेटफॉर्म पर रखकर बैठें।","अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा रखें।","अपने पैरों को फैलाने और अपने घुटनों को सीधा करने के लिए फुट प्लेटफॉर्म पर दबाव डालें।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे अपने घुटनों को मोड़कर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1391', 'Sled Calf Press On Leg Press', 'lower legs', 'calves', '["hamstrings","quadriceps"]', 'sled machine', 'strength', NULL, '["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Place your feet shoulder-width apart on the sled, with your toes pointing forward.","Release the safety handles and push the sled away from you by extending your knees and ankles.","Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.","Repeat for the desired number of repetitions."]', '["लेग प्रेस मशीन की सीट को समायोजित करें ताकि जब आपके पैर स्लेज पर हों तो आपके घुटने थोड़े मुड़े हुए हों।","अपने पैरों को स्लेज पर कंधे की चौड़ाई से अलग रखें, आपके पैर की उंगलियां आगे की ओर हों।","सुरक्षा हैंडल छोड़ें और अपने घुटनों और टखनों को फैलाकर स्लेज को अपने से दूर धकेलें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने घुटनों और टखनों को मोड़कर स्लेज को वापस नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0741', 'Sled Closer Hack Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'sled machine', 'strength', NULL, '["Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.","Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Grip the handles on the sides of the machine for stability.","Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.","Repeat for the desired number of repetitions."]', '["स्लेज मशीन को आरामदायक वजन के अनुसार समायोजित करें और अपनी पीठ को पैड के सामने रखें।","अपने पैरों को प्लेटफ़ॉर्म पर कंधे की चौड़ाई से अलग रखें, पैर की उंगलियां थोड़ी बाहर की ओर हों।","स्थिरता के लिए मशीन के किनारों पर लगे हैंडल को पकड़ें।","अपने कोर को संलग्न करें और अपनी पीठ को सीधा रखते हुए, अपने घुटनों और कूल्हों को मोड़कर धीरे-धीरे अपने शरीर को नीचे लाएँ।","जब तक आपकी जांघें जमीन के समानांतर या थोड़ा नीचे न हो जाएं तब तक नीचे करना जारी रखें।","नीचे एक क्षण के लिए रुकें, फिर अपने पैरों को फैलाने के लिए अपनी एड़ियों से धक्का दें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0742', 'Sled Forward Angled Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'sled machine', 'strength', NULL, '["Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.","Place your hands on the handles or the sides of the machine for support.","Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्लेज मशीन को एक आरामदायक वजन के अनुसार समायोजित करें और अपने पैर की उंगलियों को प्लेटफॉर्म पर और अपनी एड़ी को लटकाकर मशीन पर खुद को रखें।","समर्थन के लिए अपने हाथों को मशीन के हैंडल या किनारों पर रखें।","अपने पिंडलियों को संलग्न करें और स्लेज के प्रतिरोध के विरुद्ध दबाव डालते हुए धीरे-धीरे अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0743', 'Sled Hack Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'sled machine', 'strength', NULL, '["Adjust the sled machine to a comfortable position for your height.","Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Hold onto the handles or bars for stability.","Lower your body by bending your knees and hips, keeping your back straight and chest up.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to raise your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["स्लेज मशीन को अपनी ऊंचाई के लिए आरामदायक स्थिति में समायोजित करें।","प्लेटफ़ॉर्म पर अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","स्थिरता के लिए हैंडल या बार को पकड़ें।","अपने घुटनों और कूल्हों को मोड़कर, अपनी पीठ को सीधा और छाती को ऊपर रखते हुए अपने शरीर को नीचे लाएँ।","जब तक आपकी जांघें जमीन के समानांतर या थोड़ा नीचे न हो जाएं तब तक नीचे करना जारी रखें।","एक पल के लिए रुकें, फिर अपने शरीर को प्रारंभिक स्थिति में वापस लाने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2334', 'Sled Lying Calf Press', 'lower legs', 'calves', '["hamstrings","glutes"]', 'sled machine', 'strength', NULL, '["Adjust the sled machine to a comfortable weight.","Sit on the sled machine with your back against the pad and your feet on the platform.","Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.","Push the platform away from you by extending your ankles, keeping your knees slightly bent.","Continue pushing until your calves are fully contracted.","Hold the contraction for a moment, then slowly lower the platform back to the starting position.","Repeat for the desired number of repetitions."]', '["स्लेज मशीन को आरामदायक वजन के अनुसार समायोजित करें।","स्लेज मशीन पर अपनी पीठ पैड से सटाकर और अपने पैरों को प्लेटफॉर्म पर रखकर बैठें।","अपने पैर की अंगुलियों और पैरों की अंडकोषों को मंच के किनारे पर रखें, जबकि आपकी एड़ियां लटकी हुई हों।","अपने घुटनों को थोड़ा मोड़कर, अपनी एड़ियों को फैलाकर प्लेटफ़ॉर्म को अपने से दूर धकेलें।","तब तक जोर लगाना जारी रखें जब तक आपकी पिंडलियां पूरी तरह से सिकुड़ न जाएं।","एक पल के लिए संकुचन को रोककर रखें, फिर धीरे-धीरे प्लेटफ़ॉर्म को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0744', 'Sled Lying Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'sled machine', 'strength', NULL, '["Adjust the sled machine to a comfortable weight.","Lie on your back on the sled machine with your feet on the footplate.","Position your feet shoulder-width apart and slightly angled outwards.","Grip the handles of the sled machine for stability.","Engage your glutes and core muscles.","Push through your heels and extend your legs to lift the sled.","Lower the sled back down by bending your knees and hips.","Repeat for the desired number of repetitions."]', '["स्लेज मशीन को आरामदायक वजन के अनुसार समायोजित करें।","स्लेज मशीन पर अपनी पीठ के बल लेटें और अपने पैरों को फ़ुटप्लेट पर रखें।","अपने पैरों को कंधे की चौड़ाई से अलग और थोड़ा बाहर की ओर रखें।","स्थिरता के लिए स्लेज मशीन के हैंडल को पकड़ें।","अपने ग्लूट्स और कोर मांसपेशियों को संलग्न करें।","स्लेज को उठाने के लिए अपनी एड़ियों को दबाएं और अपने पैरों को फैलाएं।","अपने घुटनों और कूल्हों को मोड़कर स्लेज को वापस नीचे करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1392', 'Sled One Leg Calf Press On Leg Press', 'lower legs', 'calves', '["hamstrings","glutes"]', 'sled machine', 'strength', NULL, '["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.","Place your toes and the balls of your feet on the sled, keeping your heels off.","Push the sled forward by extending your ankles, keeping your knees slightly bent.","Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.","Repeat for the desired number of repetitions."]', '["लेग प्रेस मशीन की सीट को समायोजित करें ताकि जब आपके पैर स्लेज पर हों तो आपके घुटने थोड़े मुड़े हुए हों।","मशीन पर अपनी पीठ बैकरेस्ट से सटाकर और अपने पैरों को स्लेज पर कंधे की चौड़ाई की दूरी पर रखकर बैठें।","अपनी एड़ियों को दूर रखते हुए, अपने पैर की उंगलियों और अपने पैरों की उंगलियों को स्लेज पर रखें।","अपने घुटनों को थोड़ा मोड़ते हुए, अपनी एड़ियों को फैलाकर स्लेज को आगे की ओर धकेलें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को मोड़कर स्लेज को वापस नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1496', 'Sledge Hammer', 'waist', 'abs', '["forearms","shoulders"]', 'hammer', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.","Engage your core and keep your back straight.","Swing the sledge hammer down towards the ground, using your core and upper body strength.","As you swing down, pivot your hips and transfer the force to the hammer.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों से स्लेज हैमर को पकड़ लें।","अपने कोर को व्यस्त रखें और अपनी पीठ सीधी रखें।","अपने मूल और ऊपरी शरीर की ताकत का उपयोग करके स्लेज हथौड़े को नीचे जमीन की ओर घुमाएं।","जैसे ही आप नीचे झूलते हैं, अपने कूल्हों को मोड़ें और बल को हथौड़े पर स्थानांतरित करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0746', 'Smith Back Shrug', 'back', 'traps', '["shoulders"]', 'smith machine', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and allow the barbell to hang in front of your thighs.","Lift your shoulders straight up towards your ears, squeezing your traps at the top.","Hold for a moment, then lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी बाहों को सीधा रखें और बारबेल को अपनी जांघों के सामने लटकने दें।","अपने कंधों को सीधे अपने कानों की ओर उठाएं, अपने जालों को शीर्ष पर दबाएं।","एक क्षण के लिए रुकें, फिर अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0747', 'Smith Behind Neck Press', 'shoulders', 'delts', '["triceps","upper back"]', 'smith machine', 'strength', NULL, '["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Lower the bar down to the back of your neck, keeping your elbows pointing forward.","Press the bar up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन की सीट की ऊंचाई को समायोजित करें ताकि बार कंधे के स्तर पर हो।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","बार को ओवरहैंड पकड़ से पकड़ें, कंधे की चौड़ाई से थोड़ा अधिक चौड़ा।","बार को रैक से उठाएं और स्थिर रुख बनाए रखते हुए पीछे हटें।","अपनी कोहनियों को आगे की ओर रखते हुए बार को अपनी गर्दन के पीछे तक नीचे लाएँ।","बार को ऊपर की ओर तब तक दबाएँ जब तक आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बार को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0748', 'Smith Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'smith machine', 'strength', NULL, '["Adjust the height of the smith machine bar to chest level.","Lie flat on the bench with your feet firmly planted on the ground.","Grip the bar with an overhand grip slightly wider than shoulder-width apart.","Unrack the bar and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar touches your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन बार की ऊंचाई को छाती के स्तर तक समायोजित करें।","अपने पैरों को ज़मीन पर मजबूती से टिकाकर बेंच पर सीधे लेट जाएँ।","बार को कंधे की चौड़ाई से थोड़ी अधिक चौड़ी ओवरहैंड ग्रिप से पकड़ें।","बार को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे अपनी छाती की ओर नीचे करें।","जब बार आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बार को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0749', 'Smith Bent Knee Good Morning', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'smith machine', 'strength', NULL, '["Start by standing with your feet shoulder-width apart, toes pointing forward.","Place the barbell across your upper back, resting it on your traps.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to raise your torso back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर, पैर की उंगलियों को आगे की ओर रखते हुए खड़े होकर शुरुआत करें।","बारबेल को अपनी ऊपरी पीठ पर रखें, इसे अपने जाल पर टिकाएं।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपने धड़ को तब तक नीचे करें जब तक वह ज़मीन के समानांतर न हो जाए, अपनी हैमस्ट्रिंग में खिंचाव महसूस करें।","अपने धड़ को शुरुआती स्थिति में वापस उठाने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1359', 'Smith Bent Over Row', 'back', 'upper back', '["biceps","forearms"]', 'smith machine', 'strength', NULL, '["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', '["कूल्हे की ऊंचाई पर बार के साथ स्मिथ मशीन स्थापित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए बार की ओर मुंह करके खड़े हो जाएं।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","बार को ओवरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बार को अपनी निचली छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बार को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0750', 'Smith Chair Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'smith machine', 'strength', NULL, '["Adjust the height of the smith machine bar to a comfortable position.","Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन बार की ऊंचाई को आरामदायक स्थिति में समायोजित करें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपनी ऊपरी पीठ पर रखें, इसे अपने जाल पर टिकाएं।","अपने कोर को संलग्न करें और अपने घुटनों और कूल्हों को मोड़कर धीरे-धीरे अपने शरीर को नीचे लाते हुए अपनी छाती को ऊपर रखें।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0751', 'Smith Close-Grip Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'smith machine', 'strength', NULL, '["Adjust the seat height and position yourself on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपने पैरों को जमीन पर सपाट रखते हुए खुद को बेंच पर रखें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक संकीर्ण पकड़ के साथ पकड़ें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, बारबेल को अपनी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0752', 'Smith Deadlift', 'upper legs', 'glutes', '["hamstrings","quadriceps","lower back"]', 'smith machine', 'strength', NULL, '["Set up the smith machine with the bar at hip height.","Stand with your feet shoulder-width apart, toes pointing slightly outward.","Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.","Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.","Stand up straight, fully extending your hips and knees.","Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.","Repeat for the desired number of repetitions."]', '["कूल्हे की ऊंचाई पर बार के साथ स्मिथ मशीन स्थापित करें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपनी पीठ सीधी और छाती ऊपर रखते हुए कूल्हों और घुटनों पर झुकें, और बार को कंधे की चौड़ाई से थोड़ी अधिक चौड़ी पकड़ के साथ पकड़ें।","अपने कोर को संलग्न करें और अपने कूल्हों और घुटनों को फैलाकर बार को उठाएं, बार को अपने शरीर के करीब रखें।","अपने कूल्हों और घुटनों को पूरी तरह फैलाते हुए सीधे खड़े हो जाएं।","नियंत्रण बनाए रखते हुए और अपनी पीठ सीधी रखते हुए, कूल्हों और घुटनों पर झुककर बार को वापस नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0753', 'Smith Decline Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'smith machine', 'strength', NULL, '["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["डिक्लाइन बेंच को वांछित कोण पर समायोजित करें।","अपने पैरों को फुट पैड के नीचे सुरक्षित रखते हुए बेंच पर लेट जाएँ।","बारबेल को कंधे की चौड़ाई से थोड़ी अधिक चौड़ी पकड़ के साथ पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0754', 'Smith Decline Reverse-Grip Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'smith machine', 'strength', NULL, '["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन को गिरावट की स्थिति में समायोजित करें।","अपने पैरों को फुट पैड के नीचे सुरक्षित रखते हुए बेंच पर लेट जाएँ।","बारबेल को उल्टी पकड़ से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","बारबेल को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे अपनी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1433', 'Smith Front Squat (Clean Grip)', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves","core"]', 'smith machine', 'strength', NULL, '["Set up the smith machine with the barbell at shoulder height.","Stand facing the barbell with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.","Keep your chest up, back straight, and core engaged.","Lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["कंधे की ऊंचाई पर बारबेल के साथ स्मिथ मशीन स्थापित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए बारबेल की ओर मुंह करके खड़े हो जाएं।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","पीछे हटें और बारबेल को अपने सामने के कंधों पर रखें, इसे अपने कॉलरबोन और डेल्टोइड्स पर टिकाएं।","अपनी छाती ऊपर, पीठ सीधी और कोर व्यस्त रखें।","घुटनों और कूल्हों को मोड़कर अपने शरीर को नीचे लाएँ, जैसे कि कुर्सी पर पीछे बैठे हों।","जब तक आपकी जांघें जमीन के समानांतर या थोड़ा नीचे न हो जाएं तब तक नीचे करना जारी रखें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3281', 'Smith Full Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'smith machine', 'strength', NULL, '["Set up the smith machine with the barbell at shoulder height.","Stand with your feet shoulder-width apart, toes slightly turned out.","Step under the bar and position it across your upper back, resting on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar and take a step back, maintaining a stable stance.","Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["कंधे की ऊंचाई पर बारबेल के साथ स्मिथ मशीन स्थापित करें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बार के नीचे कदम रखें और इसे अपने जाल पर टिकाते हुए अपनी ऊपरी पीठ पर रखें।","बार को अपने हाथों से कंधे की चौड़ाई से थोड़ा अधिक चौड़ा करके पकड़ें।","बार को खोलें और स्थिर रुख बनाए रखते हुए एक कदम पीछे हटें।","अपनी छाती को ऊपर और कोर को व्यस्त रखते हुए, अपने कूल्हों को पीछे धकेलते हुए और अपने घुटनों को मोड़कर स्क्वाट शुरू करें।","अपने शरीर को तब तक नीचे झुकाएँ जब तक कि आपकी जाँघें ज़मीन के समानांतर न आ जाएँ, या जितना नीचे आपका लचीलापन अनुमति दे।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से ड्राइव करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0755', 'Smith Hack Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'smith machine', 'strength', NULL, '["Adjust the barbell on the smith machine to an appropriate height for your body.","Stand with your feet shoulder-width apart, toes slightly pointed outwards.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your chest up as you unrack the barbell.","Take a step back and position your feet slightly wider than shoulder-width apart.","Bend your knees and lower your body down, keeping your chest up and back straight.","Continue descending until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन पर बारबेल को अपने शरीर के लिए उचित ऊंचाई पर समायोजित करें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपने आप को बारबेल के नीचे रखें, इसे अपने ऊपरी जाल और कंधों पर टिकाएं।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को खोलते समय अपने कोर को व्यस्त रखें और अपनी छाती को ऊपर रखें।","एक कदम पीछे हटें और अपने पैरों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपने घुटनों को मोड़ें और अपने शरीर को नीचे करें, अपनी छाती को ऊपर और पीठ को सीधा रखें।","तब तक नीचे उतरना जारी रखें जब तक आपकी जांघें जमीन के समानांतर या थोड़ा नीचे न हो जाएं।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0756', 'Smith Hip Raise', 'waist', 'abs', '["glutes","hamstrings"]', 'smith machine', 'strength', NULL, '["Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.","Place your hands on the barbell, slightly wider than shoulder-width apart.","Engage your core and glutes, then push through your heels to raise your hips off the ground.","Continue lifting until your body forms a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ को पैड से सटाकर और अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए अपने आप को स्मिथ मशीन पर रखें।","अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़े बारबेल पर रखें।","अपने कोर और ग्लूट्स को शामिल करें, फिर अपने कूल्हों को ज़मीन से ऊपर उठाने के लिए अपनी एड़ी से धक्का दें।","तब तक उठाना जारी रखें जब तक आपका शरीर आपके घुटनों से लेकर आपके कंधों तक एक सीधी रेखा न बना ले।","एक क्षण के लिए शीर्ष पर रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0757', 'Smith Incline Bench Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'smith machine', 'strength', NULL, '["Adjust the bench to a 30-45 degree incline.","Sit on the bench with your back flat against the pad and feet firmly on the ground.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["बेंच को 30-45 डिग्री के झुकाव पर समायोजित करें।","अपनी पीठ को पैड से सटाकर और पैरों को ज़मीन पर मजबूती से टिकाकर बेंच पर बैठें।","बारबेल को कंधे की चौड़ाई से थोड़ी अधिक चौड़ी पकड़ के साथ पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को थोड़ा अंदर की ओर रखते हुए इसे धीरे-धीरे अपनी ऊपरी छाती की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0758', 'Smith Incline Reverse-Grip Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'smith machine', 'strength', NULL, '["Adjust the seat of the smith machine to a comfortable incline angle.","Sit on the machine with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.","Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar is just above your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन की सीट को आरामदायक झुकाव वाले कोण पर समायोजित करें।","मशीन पर अपनी पीठ पैड से सटाकर और अपने पैरों को ज़मीन पर सपाट करके बैठें।","बार को एक ओवरहैंड ग्रिप से पकड़ें जो कंधे की चौड़ाई से थोड़ी अधिक चौड़ी हो।","बार को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","जब बार आपकी छाती के ठीक ऊपर हो तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बार को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0759', 'Smith Incline Shoulder Raises', 'chest', 'serratus anterior', '["deltoids","trapezius"]', 'smith machine', 'strength', NULL, '["Adjust the smith machine to an incline position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Raise the barbell up towards the ceiling, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन को झुकी हुई स्थिति में समायोजित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","बार को ओवरहैंड पकड़ से पकड़ें, कंधे की चौड़ाई से थोड़ा अधिक चौड़ा।","अपनी पीठ सीधी और कोर व्यस्त रखें।","अपनी कोहनियों की मदद से बारबेल को छत की ओर ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0760', 'Smith Leg Press', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'smith machine', 'strength', NULL, '["Adjust the seat and footplate of the smith machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grasp the handles or sides of the machine for stability.","Push the footplate away from you by extending your legs, keeping your back against the backrest.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards you, returning to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन की सीट और फ़ुटप्लेट को आरामदायक स्थिति में समायोजित करें।","मशीन पर अपनी पीठ बैकरेस्ट से सटाकर बैठें और आपके पैर फ़ुटप्लेट पर कंधे की चौड़ाई से अलग हों।","स्थिरता के लिए मशीन के हैंडल या किनारों को पकड़ें।","अपने पैरों को फैलाकर, अपनी पीठ को बैकरेस्ट के सामने रखते हुए, फ़ुटप्लेट को अपने से दूर धकेलें।","पूरी तरह विस्तारित स्थिति में एक पल के लिए रुकें।","धीरे-धीरे अपने घुटनों को मोड़ें और फ़ुटप्लेट को वापस अपनी ओर नीचे करें, प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1434', 'Smith Low Bar Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'smith machine', 'strength', NULL, '["Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.","Stand with your feet shoulder-width apart, toes slightly turned outwards.","Step under the bar and position it across your upper back, resting it on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar by straightening your legs and stepping back from the rack.","Take a deep breath and brace your core.","Initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your chest up and your back straight throughout the movement.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन को बारबेल के साथ ऐसी ऊंचाई पर स्थापित करें जिससे आप इसे अपनी ऊपरी पीठ पर आराम से रख सकें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","बार के नीचे कदम रखें और इसे अपनी ऊपरी पीठ पर रखें, इसे अपने जाल पर टिकाएं।","बार को अपने हाथों से कंधे की चौड़ाई से थोड़ा अधिक चौड़ा करके पकड़ें।","अपने पैरों को सीधा करके और रैक से पीछे हटकर बार को खोलें।","गहरी सांस लें और अपने कोर को मजबूत करें।","अपने कूल्हों को पीछे धकेलकर और अपने घुटनों को मोड़कर स्क्वाट शुरू करें।","अपने शरीर को तब तक नीचे झुकाएँ जब तक कि आपकी जाँघें ज़मीन के समानांतर या थोड़ा नीचे न आ जाएँ।","पूरे आंदोलन के दौरान अपनी छाती को ऊपर और अपनी पीठ को सीधा रखें।","अपने कूल्हों और घुटनों को फैलाते हुए वापस खड़े होने के लिए अपनी एड़ी से ड्राइव करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1683', 'Smith Machine Bicep Curl', 'upper arms', 'biceps', '["forearms"]', 'smith machine', 'strength', NULL, '["Adjust the height of the smith machine bar to be at waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन बार की ऊंचाई को कमर के स्तर पर समायोजित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए स्मिथ मशीन की ओर मुंह करके खड़े हो जाएं।","बार को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी कोहनियों को अपनी भुजाओं के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए बार को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे बार को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1625', 'Smith Machine Decline Close Grip Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'smith machine', 'strength', NULL, '["Adjust the bench on the smith machine to a decline position.","Lie down on the bench with your feet firmly planted on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन पर बेंच को गिरावट की स्थिति में समायोजित करें।","अपने पैरों को ज़मीन पर मजबूती से टिकाकर बेंच पर लेट जाएँ।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक संकीर्ण पकड़ के साथ पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","जब बारबेल आपकी छाती के ठीक ऊपर हो तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1752', 'Smith Machine Incline Tricep Extension', 'upper arms', 'triceps', '["shoulders"]', 'smith machine', 'strength', NULL, '["Adjust the seat of the smith machine so that the bar is at shoulder height.","Sit on the bench with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.","Lower the bar slowly towards your forehead, keeping your elbows close to your head.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन की सीट को समायोजित करें ताकि बार कंधे की ऊंचाई पर हो।","बेंच पर अपनी पीठ पैड से सटाकर और अपने पैरों को ज़मीन पर सपाट करके बैठें।","बार को ओवरहैंड पकड़ से पकड़ें, कंधे की चौड़ाई से थोड़ा अधिक चौड़ा।","अपनी बाहों को पूरी तरह फैलाएं, बार को रैक से उठाएं और इसे सीधे अपनी छाती के ऊपर रखें।","अपनी कोहनियों को अपने सिर के पास रखते हुए बार को धीरे-धीरे अपने माथे की ओर नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर बार को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1626', 'Smith Machine Reverse Decline Close Grip Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'smith machine', 'strength', NULL, '["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन को गिरावट की स्थिति में समायोजित करें।","अपने पैरों को फुट पैड के नीचे सुरक्षित रखते हुए बेंच पर लेट जाएँ।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक संकीर्ण पकड़ के साथ पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0761', 'Smith Narrow Row', 'back', 'upper back', '["biceps","rear deltoids"]', 'smith machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your feet flat on the floor.","Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.","Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें और अपने पैरों को फर्श पर सपाट रखते हुए खुद को मशीन पर रखें।","हैंडल को ओवरहैंड पकड़ से पकड़ें, कंधे की चौड़ाई से थोड़ा संकरा।","जब आप हैंडल को अपने शरीर की ओर खींचते हैं, तो अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए अपनी पीठ सीधी और अपनी छाती ऊपर रखें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1360', 'Smith One Arm Row', 'back', 'upper back', '["biceps","forearms"]', 'smith machine', 'strength', NULL, '["Adjust the height of the smith machine bar to waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with one hand using an overhand grip, with your palm facing down.","Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["स्मिथ मशीन बार की ऊंचाई को कमर के स्तर तक समायोजित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए स्मिथ मशीन की ओर मुंह करके खड़े हो जाएं।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी हथेली को नीचे की ओर रखते हुए, ओवरहैंड ग्रिप का उपयोग करके एक हाथ से बार को पकड़ें।","अपनी कोहनी को अपने शरीर के पास रखें और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए बार को अपनी कमर की ओर खींचें।","आंदोलन के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बार को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1393', 'Smith One Leg Floor Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'smith machine', 'strength', NULL, '["Position yourself on the floor under the smith machine bar, facing away from the machine.","Place the balls of your feet on a raised surface, such as a weight plate or block.","Position the smith machine bar across your lower legs, just above your ankles.","Hold onto the bar with your hands for stability.","Raise your heels off the ground by extending your ankles, lifting your body up.","Pause at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने आप को मशीन से दूर की ओर मुंह करके स्मिथ मशीन बार के नीचे फर्श पर रखें।","अपने पैरों की अंडकोषों को किसी उभरी हुई सतह, जैसे वेट प्लेट या ब्लॉक पर रखें।","स्मिथ मशीन बार को अपने निचले पैरों पर, अपने टखनों के ठीक ऊपर रखें।","स्थिरता के लिए बार को अपने हाथों से पकड़ें।","अपनी एड़ियों को फैलाकर, अपने शरीर को ऊपर उठाते हुए, अपनी एड़ियों को ज़मीन से ऊपर उठाएँ।","गति के शीर्ष पर रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0762', 'Smith Rear Delt Row', 'shoulders', 'delts', '["trapezius","rhomboids","biceps"]', 'smith machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपने आप को मशीन पर इस तरह रखें कि आपकी छाती पैड से सटी हो और आपके पैर जमीन पर सपाट हों।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","जब आप हैंडल को अपनी छाती की ओर खींचते हैं, तो अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0763', 'Smith Reverse Calf Raises', 'lower legs', 'calves', '["hamstrings"]', 'smith machine', 'strength', NULL, '["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support, keeping your back straight and core engaged.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन बार को अपने कंधों के ठीक नीचे की ऊंचाई पर समायोजित करें।","अपने पैरों को कूल्हे-चौड़ाई से अलग और पैर की उंगलियों को आगे की ओर रखते हुए बार की ओर मुंह करके खड़े हो जाएं।","अपने पैरों के पंजों को किसी सीढ़ी या मंच के किनारे पर रखें, अपनी एड़ियों को लटकाते हुए।","समर्थन के लिए बार को पकड़ें, अपनी पीठ को सीधा रखें और कोर को व्यस्त रखें।","अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं, अपने शरीर का वजन अपने पैरों की उंगलियों पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1394', 'Smith Reverse Calf Raises', 'lower legs', 'calves', '["hamstrings"]', 'smith machine', 'strength', NULL, '["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support.","Raise your heels as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन बार को अपने कंधों के ठीक नीचे की ऊंचाई पर समायोजित करें।","अपने पैरों को कूल्हे-चौड़ाई से अलग और पैर की उंगलियों को आगे की ओर रखते हुए बार की ओर मुंह करके खड़े हो जाएं।","अपने पैरों के पंजों को किसी सीढ़ी या मंच के किनारे पर रखें, अपनी एड़ियों को लटकाते हुए।","समर्थन के लिए बार को पकड़ें।","अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं, अपने शरीर को अपने पंजों पर ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1361', 'Smith Reverse Grip Bent Over Row', 'back', 'upper back', '["biceps","forearms"]', 'smith machine', 'strength', NULL, '["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', '["कूल्हे की ऊंचाई पर बार के साथ स्मिथ मशीन स्थापित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए बार की ओर मुंह करके खड़े हो जाएं।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","बार को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से अलग हों।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बार को अपनी निचली छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बार को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0764', 'Smith Reverse-Grip Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'smith machine', 'strength', NULL, '["Adjust the height of the smith machine bar to chest level.","Stand facing the bar with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step back and position yourself with a slight bend in your knees.","Keep your chest up and core engaged throughout the exercise.","Lower the bar towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन बार की ऊंचाई को छाती के स्तर तक समायोजित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए बार की ओर मुंह करके खड़े हो जाएं।","बार को ओवरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","पीछे हटें और अपने घुटनों को थोड़ा मोड़कर खुद को स्थिति में रखें।","पूरे अभ्यास के दौरान अपनी छाती को ऊपर और कोर को व्यस्त रखें।","अपनी कोहनियों को अंदर की ओर रखते हुए बार को अपनी छाती की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर बार को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1395', 'Smith Seated One Leg Calf Raise', 'lower legs', 'calves', '["hamstrings"]', 'smith machine', 'strength', NULL, '["Sit on the machine with your back against the pad and your feet on the footrest.","Place one leg on the footrest and keep the other leg off the footrest.","Using your calf muscles, raise your heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["मशीन पर अपनी पीठ पैड से सटाकर और अपने पैरों को फ़ुटरेस्ट पर रखकर बैठें।","एक पैर को फ़ुटरेस्ट पर रखें और दूसरे पैर को फ़ुटरेस्ट से दूर रखें।","अपनी पिंडली की मांसपेशियों का उपयोग करते हुए, अपनी एड़ी को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0765', 'Smith Seated Shoulder Press', 'shoulders', 'delts', '["triceps","upper back"]', 'smith machine', 'strength', NULL, '["Adjust the seat height so that the handles are at shoulder level.","Sit on the machine with your back against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.","Lower the handles down to shoulder level, keeping your elbows slightly bent.","Press the handles up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें ताकि हैंडल कंधे के स्तर पर हों।","मशीन पर अपनी पीठ पैड से सटाकर और अपने पैरों को फर्श पर सपाट करके बैठें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी बाहों को पूरी तरह फैलाते हुए उन्हें सपोर्ट से ऊपर उठाएं।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, हैंडल को कंधे के स्तर तक नीचे लाएँ।","जब तक आपकी बाहें पूरी तरह विस्तारित न हो जाएं तब तक हैंडल को ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को वापस कंधे के स्तर तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1426', 'Smith Seated Wrist Curl', 'lower arms', 'forearms', '["biceps","brachialis"]', 'smith machine', 'strength', NULL, '["Sit on a bench in front of a Smith machine with your feet flat on the ground.","Grasp the barbell with an underhand grip, hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन के सामने एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके बैठें।","बारबेल को अंडरहैंड पकड़ से पकड़ें, हाथ कंधे की चौड़ाई से अलग।","अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ, जिससे आपकी कलाइयाँ लटक जाएँ।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, बारबेल को अपने अग्रबाहुओं की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0766', 'Smith Shoulder Press', 'shoulders', 'delts', '["triceps","upper back"]', 'smith machine', 'strength', NULL, '["Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.","Press the bar upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the bar back down to shoulder level.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए अपने आप को स्मिथ मशीन पर रखें।","बार को ओवरहैंड पकड़ से पकड़ें, कंधे की चौड़ाई से थोड़ा अधिक चौड़ा।","बार को रैक से उठाएं और इसे कंधे के स्तर पर रखें, अपनी कोहनी मुड़ी हुई और हथेलियाँ आगे की ओर रखें।","बार को तब तक ऊपर की ओर दबाएं जब तक कि आपकी भुजाएं पूरी तरह से ऊपर की ओर न फैल जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बार को वापस कंधे के स्तर तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0767', 'Smith Shrug', 'back', 'traps', '["shoulders"]', 'smith machine', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and your shoulders relaxed.","Lift your shoulders up towards your ears, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी भुजाओं को सीधा रखें और अपने कंधों को शिथिल रखें।","अपने कंधों को अपने कानों की ओर ऊपर उठाएं, अपने जालों को शीर्ष पर दबाएं।","एक पल के लिए रुकें, फिर धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0768', 'Smith Single Leg Split Squat', 'upper legs', 'quads', '["glutes","hamstrings"]', 'smith machine', 'strength', 'beginner', '["Stand in front of the smith machine with your feet shoulder-width apart.","Place one foot behind you on a bench or step, with your toes pointing forward.","Hold onto the smith machine bar for stability.","Bend your front knee and lower your body down into a lunge position, keeping your back straight.","Pause for a moment at the bottom, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए स्मिथ मशीन के सामने खड़े हो जाएं।","एक पैर को अपने पीछे किसी बेंच या सीढ़ी पर रखें, जिसमें आपके पैर की उंगलियां आगे की ओर हों।","स्थिरता के लिए स्मिथ मशीन बार को पकड़ें।","अपने सामने के घुटने को मोड़ें और अपनी पीठ को सीधा रखते हुए अपने शरीर को नीचे की ओर झुकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी सामने की एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', '["Smith_Single-Leg_Split_Squat/0.jpg","Smith_Single-Leg_Split_Squat/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0769', 'Smith Sprint Lunge', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'smith machine', 'strength', NULL, '["Set up the smith machine with the barbell at hip height.","Stand facing away from the machine with your feet shoulder-width apart.","Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.","Bend your left knee and lower your body into a lunge position, keeping your back straight.","Push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot.","Continue alternating sides for the desired number of repetitions."]', '["कूल्हे की ऊंचाई पर बारबेल के साथ स्मिथ मशीन स्थापित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","अपने दाहिने पैर के साथ पीछे हटें और इसे बारबेल पर रखें, अपने पैर के शीर्ष को बार पर टिकाएं।","अपने बाएं घुटने को मोड़ें और अपनी पीठ को सीधा रखते हुए अपने शरीर को लंज स्थिति में नीचे लाएं।","प्रारंभिक स्थिति में लौटने के लिए अपनी बायीं एड़ी को धक्का दें।","अपने बाएं पैर से पीछे हटते हुए दूसरी तरफ भी दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 9.8, 'sets', 0, 'opengym', 1),
('og-0770', 'Smith Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'smith machine', 'strength', NULL, '["Set up the smith machine with the barbell at an appropriate height for your squat.","Stand with your feet shoulder-width apart, toes slightly turned out.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grip the barbell with a wide grip, slightly wider than shoulder-width apart.","Engage your core and unrack the barbell, stepping back to clear the rack.","Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने स्क्वाट के लिए उचित ऊंचाई पर बारबेल के साथ स्मिथ मशीन स्थापित करें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","अपने आप को बारबेल के नीचे रखें, इसे अपने ऊपरी जाल और कंधों पर टिकाएं।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़ी पकड़ के साथ पकड़ें।","अपने कोर को संलग्न करें और रैक को साफ़ करने के लिए पीछे हटते हुए बारबेल को खोलें।","अपनी छाती को ऊपर और पीठ को सीधा रखते हुए, कूल्हों और घुटनों पर झुककर स्क्वाट शुरू करें।","अपने शरीर को तब तक नीचे झुकाएँ जब तक कि आपकी जाँघें ज़मीन के समानांतर या थोड़ा नीचे न आ जाएँ।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से ड्राइव करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0771', 'Smith Standing Back Wrist Curl', 'lower arms', 'forearms', '["biceps","triceps"]', 'smith machine', 'strength', NULL, '["Stand facing the smith machine with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, hands shoulder-width apart.","Keep your back straight and your elbows close to your body.","Slowly curl your wrists upwards, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए स्मिथ मशीन की ओर मुंह करके खड़े हो जाएं।","हाथों को कंधे की चौड़ाई से अलग रखते हुए बारबेल को ओवरहैंड पकड़ से पकड़ें।","अपनी पीठ सीधी रखें और अपनी कोहनियाँ अपने शरीर के पास रखें।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, बारबेल को अपने शरीर की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0772', 'Smith Standing Behind Head Military Press', 'shoulders', 'delts', '["triceps","upper back"]', 'smith machine', 'strength', NULL, '["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Position the bar behind your head, resting on your upper traps.","Keep your core engaged and your chest lifted throughout the exercise.","Press the bar overhead by extending your arms, fully straightening them.","Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन की सीट की ऊंचाई को समायोजित करें ताकि बार कंधे के स्तर पर हो।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","बार को ओवरहैंड पकड़ से पकड़ें, कंधे की चौड़ाई से थोड़ा अधिक चौड़ा।","बार को रैक से उठाएं और स्थिर रुख बनाए रखते हुए पीछे हटें।","अपने ऊपरी जाल पर आराम करते हुए बार को अपने सिर के पीछे रखें।","पूरे अभ्यास के दौरान अपने कोर को व्यस्त रखें और अपनी छाती को ऊपर उठाएं।","अपनी भुजाओं को फैलाकर, उन्हें पूरी तरह सीधा करके, बार को ऊपर की ओर दबाएं।","आंदोलन के शीर्ष पर कुछ देर रुकें, फिर धीरे-धीरे बार को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0773', 'Smith Standing Leg Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'smith machine', 'strength', NULL, '["Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.","Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.","Place your hands on the bar for stability.","Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन बार को इतनी ऊंचाई पर समायोजित करें कि आप अपने पैरों को जमीन पर सपाट करके और अपने कंधों को बार के नीचे रखकर खड़े हो सकें।","अपने पैरों को कंधे की चौड़ाई पर अलग रखते हुए और अपने पैर की उंगलियों को आगे की ओर रखते हुए अपने आप को बार के नीचे रखें।","स्थिरता के लिए अपने हाथों को बार पर रखें।","अपने पिंडलियों को संलग्न करें और धीरे-धीरे अपनी एड़ियों को जमीन से ऊपर उठाएं, अपने शरीर को अपने पैर की उंगलियों पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0774', 'Smith Standing Military Press', 'shoulders', 'delts', '["triceps","upper back"]', 'smith machine', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.","Press the barbell upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को रैक से उठाएं और अपनी हथेलियों को आगे की ओर रखते हुए कंधे के स्तर तक नीचे लाएं।","बारबेल को तब तक ऊपर की ओर दबाएं जब तक कि आपकी भुजाएं पूरी तरह से ऊपर की ओर विस्तारित न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस कंधे के स्तर तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3142', 'Smith Sumo Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'smith machine', 'strength', NULL, '["Set up the smith machine with the barbell at hip height.","Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Position yourself under the barbell, resting it on your upper back and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["कूल्हे की ऊंचाई पर बारबेल के साथ स्मिथ मशीन स्थापित करें।","अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां बाहर की ओर हों।","अपने आप को बारबेल के नीचे रखें, इसे अपनी ऊपरी पीठ और कंधों पर टिकाएं।","अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें क्योंकि आप अपने शरीर को स्क्वाट स्थिति में नीचे लाते हैं, अपने कूल्हों को पीछे धकेलते हैं और अपने घुटनों को मोड़ते हैं।","अपने आप को तब तक नीचे करें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या जितना नीचे आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1396', 'Smith Toe Raise', 'lower legs', 'calves', '["ankles","shins"]', 'smith machine', 'strength', NULL, '["Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.","Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.","Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your back straight throughout the exercise.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन बार को इतनी ऊंचाई पर समायोजित करें कि आप आराम से अपने पैरों को जमीन पर सपाट रखकर खड़े हो सकें।","अपने आप को बार के नीचे इस प्रकार रखें कि आपके कंधे सीधे उसके नीचे हों और आपके पैर कंधे की चौड़ाई से अलग हों।","अपने पैरों की उंगलियों को एक ऊंचे मंच या वेट प्लेट पर रखें, जिसमें आपकी एड़ियाँ किनारे से लटकी हुई हों।","बार को ओवरहैंड पकड़ से पकड़ें, कंधे की चौड़ाई से थोड़ा अधिक चौड़ा।","पूरे अभ्यास के दौरान अपने कोर को व्यस्त रखें और अपनी पीठ सीधी रखें।","धीरे-धीरे अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं, अपने शरीर का वजन अपने पैरों की उंगलियों पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0775', 'Smith Upright Row', 'shoulders', 'delts', '["traps","biceps"]', 'smith machine', 'strength', NULL, '["Stand with your feet shoulder-width apart, facing the smith machine.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell up towards your chin, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन की ओर मुंह करके अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े हो जाएं।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपनी कोहनियों की सहायता से बारबेल को अपनी ठुड्डी की ओर ऊपर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1308', 'Smith Wide Grip Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'smith machine', 'strength', NULL, '["Adjust the bench to a comfortable position on the smith machine.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन पर बेंच को आरामदायक स्थिति में समायोजित करें।","अपने पैरों को ज़मीन पर सपाट करके बेंच पर लेट जाएँ।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़ी पकड़ से पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को बगल की ओर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1309', 'Smith Wide Grip Decline Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'smith machine', 'strength', NULL, '["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["डिक्लाइन बेंच को वांछित कोण पर समायोजित करें।","अपने पैरों को फुट पैड के नीचे सुरक्षित रखते हुए बेंच पर लेट जाएँ।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़ी पकड़ से पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को बाहर की ओर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0776', 'Snatch Pull', 'upper legs', 'quads', '["hamstrings","glutes","calves"]', 'barbell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.","Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.","Catch the barbell overhead with your arms fully extended and your knees bent.","Stand up by extending your hips and knees, keeping the barbell overhead.","Lower the barbell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल आपके सामने जमीन पर हो।","अपने घुटनों को मोड़ें और कूल्हों पर टिकाकर स्क्वाट स्थिति में आ जाएं, बारबेल को ओवरहैंड ग्रिप से पकड़ें।","बारबेल को जमीन से ऊपर उठाने के लिए अपनी एड़ी के माध्यम से ड्राइव करते समय अपनी पीठ सीधी और छाती ऊपर रखें, अपने कूल्हों और घुटनों को फैलाएं।","जैसे ही बारबेल कूल्हे के स्तर पर पहुंचती है, इसे तेजी से ऊपर की ओर खींचें, अपने कंधों को सिकोड़ें और अपनी कोहनियों को ऊंचा और बगल की ओर खींचें।","जैसे ही बारबेल अपने उच्चतम बिंदु पर पहुँचता है, तुरंत उसके नीचे आ जाएँ, अपने आप को गहरी स्क्वाट स्थिति में खींच लें।","अपनी बाहों को पूरी तरह फैलाकर और अपने घुटनों को मोड़कर बारबेल को ऊपर की ओर पकड़ें।","बारबेल को सिर के ऊपर रखते हुए, अपने कूल्हों और घुटनों को फैलाकर खड़े हो जाएं।","चाल को उलट कर बारबेल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Snatch_Pull/0.jpg","Snatch_Pull/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0777', 'Spell Caster', 'waist', 'abs', '["obliques","lower back"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend your knees slightly and hinge forward at the waist, keeping your back straight.","Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में डंबल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कमर को आगे की ओर झुकाएं।","अपने हाथ को डंबल के साथ विपरीत पैर की ओर बढ़ाएं, ऐसा करते समय अपने धड़ को घुमाएं।","प्रारंभिक स्थिति पर लौटें और दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', '["Spell_Caster/0.jpg","Spell_Caster/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1362', 'Sphinx', 'back', 'spine', '["glutes","hamstrings"]', 'body weight', 'strength', NULL, '["Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.","Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.","Hold this position for a few seconds, making sure to keep your neck in a neutral position.","Slowly lower your chest back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने अग्रबाहुओं को फर्श पर सपाट रखते हुए, कोहनियों को सीधे अपने कंधों के नीचे रखते हुए, जमीन पर मुंह करके लेट जाएं।","अपने कोर को संलग्न करें और अपनी छाती को जमीन से ऊपर उठाएं, अपने अग्रभागों और पैर की उंगलियों को फर्श पर रखें।","कुछ सेकंड के लिए इस स्थिति में रहें, यह सुनिश्चित करें कि आपकी गर्दन तटस्थ स्थिति में रहे।","धीरे-धीरे अपनी छाती को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0778', 'Spider Crawl Push Up', 'upper legs', 'glutes', '["core","chest","shoulders"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Bring your right knee towards your right elbow, keeping it off the ground.","As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.","Push back up to the starting position and repeat with your left knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा और अपने पैरों को एक साथ रखकर पुश-अप स्थिति में शुरुआत करें।","अपने दाहिने घुटने को अपनी दाहिनी कोहनी की ओर लाएँ, इसे ज़मीन से दूर रखें।","जैसे ही आप अपने दाहिने घुटने को पीछे लाते हैं, साथ ही अपनी कोहनियों को मोड़ते हुए अपने शरीर को ज़मीन की ओर नीचे लाएँ।","प्रारंभिक स्थिति में वापस आएँ और अपने बाएँ घुटने से अपनी बाएँ कोहनी की ओर दोहराएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1363', 'Spine Stretch', 'back', 'spine', '["hamstrings","glutes"]', 'body weight', 'strength', NULL, '["Sit on the ground with your legs extended in front of you.","Place your hands on the ground behind you, fingers pointing towards your body.","Engage your core and slowly lean back, keeping your back straight.","Continue leaning back until you feel a stretch in your spine.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सामने फैलाकर जमीन पर बैठें।","अपने हाथों को अपने पीछे ज़मीन पर रखें, उंगलियाँ आपके शरीर की ओर हों।","अपने कोर को संलग्न करें और अपनी पीठ को सीधा रखते हुए धीरे-धीरे पीछे झुकें।","जब तक आप अपनी रीढ़ में खिंचाव महसूस न करें तब तक पीछे झुकते रहें।","कुछ सेकंड के लिए खिंचाव बनाए रखें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2329', 'Spine Twist', 'waist', 'abs', '["obliques","lower back"]', 'body weight', 'strength', NULL, '["Sit on the ground with your legs extended in front of you.","Bend your knees and place your feet flat on the ground, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side, bringing your left elbow towards your right knee.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को सामने फैलाकर जमीन पर बैठें।","अपने घुटनों को मोड़ें और अपने पैरों को ज़मीन पर सपाट रखें, कूल्हे की चौड़ाई से अलग।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को संलग्न करें और धीरे-धीरे अपने धड़ को दाईं ओर मोड़ें, अपनी दाहिनी कोहनी को अपने बाएं घुटने की ओर लाएं।","मोड़ के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","बाईं ओर मोड़ को दोहराएं, अपनी बाईं कोहनी को अपने दाहिने घुटने की ओर लाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2368', 'Split Squats', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Take a step forward with one foot and place it about two feet in front of the other foot.","Lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","एक पैर के साथ एक कदम आगे बढ़ाएं और इसे दूसरे पैर के सामने लगभग दो फीट रखें।","अपने घुटनों और कूल्हों को मोड़कर, अपनी पीठ को सीधा रखते हुए अपने शरीर को नीचे लाएँ।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी अगली जांघ ज़मीन के समानांतर न हो जाए, और आपका पिछला घुटना ज़मीन के ठीक ऊपर न हो जाए।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी सामने की एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0786', 'Squat Jerk', 'upper legs', 'quads', '["glutes","hamstrings","calves","core"]', 'barbell', 'strength', 'expert', '["Start with the barbell resting on your shoulders, with your feet shoulder-width apart.","Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.","As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.","As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.","Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.","Stand up from the split position, bringing your feet back together.","Lower the barbell back to your shoulders and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए बारबेल को अपने कंधों पर टिकाकर शुरुआत करें।","अपने शरीर को स्क्वाट स्थिति में लाएँ, अपनी छाती को ऊपर रखें और अपने घुटनों को अपने पैर की उंगलियों पर रखें।","जैसे ही आप स्क्वाट के निचले भाग तक पहुँचते हैं, अपने पैरों के माध्यम से विस्फोटक रूप से ड्राइव करें और बारबेल को ऊपर की ओर धकेलें।","जैसे ही बारबेल अपने चरम पर पहुंचती है, तुरंत एक पैर आगे और एक पैर पीछे करके विभाजित स्थिति में आ जाएं।","अपनी भुजाओं को पूरी तरह फैलाकर और अपने पिछले घुटने को थोड़ा जमीन से छूते हुए बारबेल को ऊपर की ओर पकड़ें।","अपने पैरों को वापस एक साथ लाते हुए, विभाजित स्थिति से खड़े हो जाएं।","बारबेल को वापस अपने कंधों तक नीचे लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', '["Squat_Jerk/0.jpg","Squat_Jerk/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1705', 'Squat On Bosu Ball', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'bosu ball', 'strength', NULL, '["Place the bosu ball on the ground with the flat side up.","Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.","Lower your body down by bending your knees and hips, as if sitting back into a chair.","Keep your chest up and your weight on your heels.","Lower yourself until your thighs are parallel to the ground.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["बोसु बॉल को समतल सतह ऊपर की ओर करके जमीन पर रखें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने आप को बोसु बॉल के ऊपर रखें।","अपने घुटनों और कूल्हों को मोड़कर अपने शरीर को नीचे नीचे करें, जैसे कि आप किसी कुर्सी पर पीछे बैठे हों।","अपनी छाती ऊपर रखें और अपना वजन अपनी एड़ियों पर रखें।","अपने आप को तब तक नीचे रखें जब तक आपकी जांघें ज़मीन के समानांतर न हो जाएं।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1685', 'Squat To Overhead Reach', 'upper legs', 'quads', '["glutes","hamstrings","core"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body down into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, extend your arms overhead, reaching towards the ceiling.","Return to the starting position by lowering your arms and bending your knees to squat down again.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और पंजों को थोड़ा बाहर की ओर करके खड़े हो जाएं।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","जैसे ही आप स्क्वाट से ऊपर आएं, अपनी बाहों को छत की ओर बढ़ाते हुए ऊपर की ओर फैलाएं।","अपनी भुजाओं को नीचे करके और घुटनों को मोड़कर फिर से बैठ कर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1686', 'Squat To Overhead Reach With Twist', 'upper legs', 'quads', '["glutes","hamstrings","core"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, raise your arms overhead and twist your torso to one side.","Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.","Continue alternating sides with each squat repetition."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और पंजों को थोड़ा बाहर की ओर करके खड़े हो जाएं।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ।","जैसे ही आप स्क्वाट से ऊपर आएं, अपनी बाहों को ऊपर उठाएं और अपने धड़ को एक तरफ मोड़ें।","प्रारंभिक स्थिति पर लौटें और स्क्वाट दोहराएं, इस बार अपने धड़ को विपरीत दिशा में घुमाएं।","प्रत्येक स्क्वाट दोहराव के साथ पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2297', 'Stability Ball Crunch (Full Range Hands Behind Head)', 'waist', 'abs', '["hip flexors"]', 'stability ball', 'strength', NULL, '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your upper body back to the starting position.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल पर अपने पैरों को ज़मीन पर सपाट करके बैठें और आपके घुटने 90 डिग्री के कोण पर मुड़े हों।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को आगे की ओर मोड़ें, अपनी छाती को अपने घुटनों की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3291', 'Stalder Press', 'upper arms', 'triceps', '["shoulders","core"]', 'body weight', 'strength', NULL, '["Start by standing with your feet shoulder-width apart and your arms extended overhead.","Bend your knees slightly and engage your core.","Lower your body down into a squat position while keeping your arms extended overhead.","As you squat down, press your arms down towards the ground, engaging your triceps.","Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और अपनी बाहों को ऊपर की ओर फैलाकर खड़े होकर शुरुआत करें।","अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें।","अपनी बाहों को ऊपर की ओर फैलाते हुए अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","जैसे ही आप बैठते हैं, अपनी ट्राइसेप्स को जोड़ते हुए अपनी बाहों को जमीन की ओर दबाएं।","स्क्वाट के निचले हिस्से में एक पल के लिए रुकें, फिर वापस खड़े होने के लिए अपनी एड़ियों को धक्का दें और साथ ही अपनी बाहों को ऊपर की ओर उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3669', 'Standing Archer', 'back', 'upper back', '["shoulders","biceps","forearms"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you at shoulder height, parallel to the ground.","Rotate your torso to the right, keeping your arms extended and your back straight.","As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.","Hold the position for a moment, then return to the starting position.","Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","अपनी भुजाओं को ज़मीन के समानांतर कंधे की ऊंचाई पर अपने सामने सीधा फैलाएं।","अपने धड़ को दाईं ओर घुमाएं, अपनी बाहों को फैलाएं और अपनी पीठ को सीधा रखें।","जैसे ही आप घूमते हैं, धनुष की डोरी खींचने की गति की नकल करते हुए अपने दाहिने हाथ को आगे की ओर और अपने बाएं हाथ को पीछे की ओर फैलाएं।","एक क्षण के लिए इस स्थिति में रहें, फिर प्रारंभिक स्थिति में लौट आएं।","गति को दोहराएं, इस बार अपने धड़ को बाईं ओर घुमाएं और अपने बाएं हाथ को आगे और अपने दाहिने हाथ को पीछे की ओर फैलाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0788', 'Standing Behind Neck Press', 'shoulders', 'delts', '["triceps","upper back"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.","Keep your back straight and core engaged.","Press the barbell overhead by extending your arms, fully extending your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल को अपनी गर्दन के पीछे एक ऊपरी पकड़ से पकड़ें।","अपनी पीठ सीधी और कोर व्यस्त रखें।","अपनी बाहों को फैलाकर, अपनी कोहनियों को पूरी तरह फैलाकर बारबेल को ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1490', 'Standing Calf Raise (On A Staircase)', 'lower legs', 'calves', '["ankles","feet"]', 'body weight', 'strength', NULL, '["Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.","Hold onto a railing or wall for balance if needed.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["किसी सीढ़ी या मजबूत मंच के किनारे पर अपनी एड़ियाँ लटकाकर और अपने पैर की उंगलियों को सीढ़ी पर रखकर खड़े हो जाएँ।","यदि आवश्यक हो तो संतुलन के लिए रेलिंग या दीवार को पकड़ें।","धीरे-धीरे अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं, अपने शरीर का वजन अपने पैरों की उंगलियों पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 9, 'sets', 0, 'opengym', 1),
('og-1397', 'Standing Calves', 'lower legs', 'calves', '["hamstrings","glutes"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes pointing forward.","Raise your heels off the ground as high as possible, standing on your toes.","Hold the position for a moment, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां आगे की ओर हों।","अपने पैर की उंगलियों पर खड़े होकर, अपनी एड़ियों को जमीन से जितना संभव हो उतना ऊपर उठाएं।","एक क्षण के लिए इस स्थिति में रहें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1398', 'Standing Calves Calf Stretch', 'lower legs', 'calves', '["hamstrings","glutes"]', 'body weight', 'strength', NULL, '["Stand facing a wall or sturdy object, about an arm''s length away.","Place your hands on the wall or object at shoulder height.","Step back with one foot, keeping your heel flat on the ground.","Bend your front knee slightly and lean forward, keeping your back leg straight.","You should feel a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Repeat on the other leg."]', '["लगभग एक हाथ की दूरी पर किसी दीवार या मजबूत वस्तु की ओर मुंह करके खड़े हो जाएं।","अपने हाथों को कंधे की ऊंचाई पर दीवार या वस्तु पर रखें।","अपनी एड़ी को ज़मीन पर सपाट रखते हुए एक पैर से पीछे हटें।","अपने सामने के घुटने को थोड़ा मोड़ें और अपने पिछले पैर को सीधा रखते हुए आगे की ओर झुकें।","आपको अपनी पिंडली की मांसपेशियों में खिंचाव महसूस होना चाहिए।","20-30 सेकंड तक खिंचाव बनाए रखें।","दूसरे पैर पर दोहराएँ."]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1599', 'Standing Hamstring And Calf Stretch With Strap', 'upper legs', 'hamstrings', '["calves"]', 'rope', 'strength', NULL, '["Stand upright with your feet shoulder-width apart.","Hold the strap with both hands and place it around the ball of your foot.","Keep your leg straight and slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your hamstring and calf muscles.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat with the other leg.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं।","दोनों हाथों से पट्टा पकड़ें और इसे अपने पैर की गेंद के चारों ओर रखें।","अपने पैर को सीधा रखें और अपनी पीठ को सीधा रखते हुए धीरे-धीरे अपने कूल्हों से आगे की ओर झुकें।","अपनी हैमस्ट्रिंग और पिंडली की मांसपेशियों में खिंचाव महसूस करें।","20-30 सेकंड तक खिंचाव बनाए रखें।","खिंचाव छोड़ें और दूसरे पैर से दोहराएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0794', 'Standing Lateral Stretch', 'back', 'lats', '["shoulders","obliques"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out to the sides, parallel to the ground.","Slowly lean your upper body to one side, feeling a stretch in your side and lats.","Hold the stretch for 15-30 seconds.","Return to the starting position and repeat on the other side.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","अपनी भुजाओं को ज़मीन के समानांतर, भुजाओं तक सीधा फैलाएँ।","धीरे-धीरे अपने ऊपरी शरीर को एक तरफ झुकाएं, अपनी बाजू और जांघों में खिंचाव महसूस करें।","15-30 सेकंड तक खिंचाव बनाए रखें।","प्रारंभिक स्थिति पर लौटें और दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1364', 'Standing Pelvic Tilt', 'back', 'spine', '["abdominals"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or let them hang by your sides.","Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.","Hold the position for a few seconds, then release and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","अपने हाथों को अपने कूल्हों पर रखें या उन्हें अपने बगल में लटका दें।","अपनी मुख्य मांसपेशियों को शामिल करें और अपनी श्रोणि को आगे की ओर झुकाएं, अपनी पीठ के निचले हिस्से को अपने पीछे की दीवार की ओर धकेलें।","कुछ सेकंड के लिए इस स्थिति में रहें, फिर छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0795', 'Standing Single Leg Curl', 'upper legs', 'hamstrings', '["glutes"]', 'body weight', 'strength', NULL, '["Stand with your feet hip-width apart and your hands on your hips.","Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.","Slowly curl your right heel towards your glutes, squeezing your hamstring.","Pause for a moment at the top, then slowly lower your right foot back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने पैरों को कूल्हे की चौड़ाई पर फैलाकर और अपने हाथों को अपने कूल्हों पर रखकर खड़े हो जाएं।","अपना वजन अपने बाएं पैर पर डालें और अपने दाहिने पैर को घुटने मोड़ते हुए जमीन से ऊपर उठाएं।","अपनी हैमस्ट्रिंग को निचोड़ते हुए धीरे-धीरे अपनी दाहिनी एड़ी को अपने ग्लूट्स की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने दाहिने पैर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0796', 'Standing Wheel Rollerout', 'waist', 'abs', '["lower back","shoulders"]', 'wheel roller', 'strength', NULL, '["Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.","Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.","Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.","Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और व्हील रोलर को अपने सामने रखकर सीधे खड़े होकर शुरुआत करें।","अपनी कमर को मोड़ें और धीरे-धीरे पहिये को आगे की ओर घुमाएँ, अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","तब तक आगे बढ़ते रहें जब तक आपको अपने पेट में खिंचाव महसूस न हो जाए और आपका शरीर जितना संभव हो उतना खिंच न जाए।","एक पल के लिए रुकें, फिर धीरे-धीरे पहिये को अपने शरीर की ओर घुमाएँ, प्रारंभिक स्थिति में लौट आएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3223', 'Star Jump (Male)', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'body weight', 'cardio', NULL, '["Stand with your feet shoulder-width apart and your arms by your sides.","Bend your knees slightly and jump up explosively.","As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.","Land softly on the balls of your feet with your knees slightly bent.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और अपनी बांहों को बगल में रखकर खड़े हो जाएं।","अपने घुटनों को थोड़ा मोड़ें और विस्फोटक तरीके से ऊपर कूदें।","जैसे ही आप कूदते हैं, अपने पैरों को फैलाएं और अपनी भुजाओं को बगल की ओर फैलाएं, जिससे आपके शरीर के साथ एक तारे का आकार बन जाए।","अपने घुटनों को थोड़ा मोड़कर अपने पैरों के पंजों पर धीरे से लैंड करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-2138', 'Stationary Bike Run v. 3', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'stationary bike', 'cardio', NULL, '["Adjust the seat height and position to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace.","Maintain a steady rhythm and increase the resistance as desired.","Engage your core muscles to maintain stability and proper posture.","Continue pedaling for the desired duration of your workout.","Gradually decrease the resistance and slow down before coming to a complete stop.","Stretch your legs and cool down after the workout."]', '["उचित संरेखण सुनिश्चित करने के लिए सीट की ऊंचाई और स्थिति को समायोजित करें।","अपने पैरों को पैडल पर रखें और यदि उपलब्ध हो तो उन्हें पट्टियों से सुरक्षित करें।","आरामदायक गति से पैडल चलाना शुरू करें।","एक स्थिर लय बनाए रखें और इच्छानुसार प्रतिरोध बढ़ाएँ।","स्थिरता और उचित मुद्रा बनाए रखने के लिए अपनी मुख्य मांसपेशियों को संलग्न करें।","अपने वर्कआउट की वांछित अवधि तक पैडल चलाना जारी रखें।","प्रतिरोध को धीरे-धीरे कम करें और पूरी तरह रुकने से पहले धीमा करें।","वर्कआउट के बाद अपने पैरों को फैलाएं और ठंडा हो जाएं।"]', NULL, 9.8, 'time', 0, 'opengym', 1),
('og-0798', 'Stationary Bike Walk', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'leverage machine', 'cardio', NULL, '["Adjust the seat height and position on the stationary bike to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace, keeping your back straight and core engaged.","Maintain a steady rhythm and increase the resistance level if desired.","Continue pedaling for the desired duration of your cardio workout.","Cool down by gradually reducing your pace and resistance level.","Stretch your leg muscles after the workout to prevent tightness and promote recovery."]', '["उचित संरेखण सुनिश्चित करने के लिए स्थिर बाइक पर सीट की ऊंचाई और स्थिति को समायोजित करें।","अपने पैरों को पैडल पर रखें और यदि उपलब्ध हो तो उन्हें पट्टियों से सुरक्षित करें।","अपनी पीठ सीधी और मुख्य भाग को व्यस्त रखते हुए, आरामदायक गति से पैडल चलाना शुरू करें।","एक स्थिर लय बनाए रखें और यदि चाहें तो प्रतिरोध स्तर बढ़ाएँ।","अपने कार्डियो वर्कआउट की वांछित अवधि तक पैडल चलाना जारी रखें।","अपनी गति और प्रतिरोध स्तर को धीरे-धीरे कम करके शांत हो जाएँ।","कसरत के बाद जकड़न को रोकने और रिकवरी को बढ़ावा देने के लिए अपने पैरों की मांसपेशियों को स्ट्रेच करें।"]', NULL, 3.5, 'time', 0, 'opengym', 1),
('og-3314', 'Straddle Maltese', 'waist', 'abs', '["shoulders","chest"]', 'body weight', 'strength', NULL, '["Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.","Spread your legs wide apart, forming a straddle position.","Engage your core and slowly lower your body until your arms are parallel to the ground.","Hold this position for a few seconds, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी बांहों को पूरी तरह फैलाकर और अपने शरीर को एक सीधी रेखा में रखकर छल्ले की एक जोड़ी से लटकना शुरू करें।","पैर फैलाकर बैठने की स्थिति बनाते हुए अपने पैरों को फैला लें।","अपने कोर को संलग्न करें और धीरे-धीरे अपने शरीर को नीचे लाएं जब तक कि आपकी भुजाएं जमीन के समानांतर न हो जाएं।","कुछ सेकंड के लिए इस स्थिति में रहें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3298', 'Straddle Planche', 'waist', 'abs', '["shoulders","triceps","chest"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.","Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.","Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई पर फैलाकर और अपने पैरों को फैलाकर पुश-अप स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और अपने कंधों को अपने हाथों के ऊपर लाते हुए धीरे-धीरे अपना वजन आगे बढ़ाएं।","अपनी कोहनियों को मोड़ें और अपने शरीर को ज़मीन की ओर नीचे करें, अपनी कोहनियों को अपनी भुजाओं के पास रखें।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करने के लिए अपने हाथों से धक्का दें और अपने शरीर को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1427', 'Straight Leg Outer Hip Abductor', 'upper legs', 'abductors', '["glutes","hamstrings"]', 'body weight', 'strength', NULL, '["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को सीधा और एक दूसरे के ऊपर रखकर करवट से लेटें।","समर्थन के लिए अपनी निचली भुजा को अपने सिर के नीचे रखें।","अपने कोर को संलग्न करें और अपने कूल्हों को घुमाए बिना या पीछे की ओर झुके बिना अपने ऊपरी पैर को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0803', 'Superman Push-Up', 'chest', 'pectorals', '["core","shoulders"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.","Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.","Repeat the movement, this time lifting your left arm and right leg.","Continue alternating sides for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा और अपने पैरों को एक साथ मिलाकर एक ऊंचे तख़्ते की स्थिति से शुरुआत करें।","अपने कोर को संलग्न करें और अपने शरीर को ज़मीन की ओर नीचे करें, अपनी कोहनियों को अपने किनारों के पास रखें।","जैसे ही आप अपने शरीर को नीचे लाते हैं, साथ ही अपने दाहिने हाथ और बाएं पैर को जमीन से ऊपर उठाएं, उन्हें सीधा फैलाएं।","शीर्ष पर एक पल के लिए रुकें, फिर अपने हाथ और पैर को वापस नीचे लाएं और खुद को शुरुआती स्थिति में वापस धकेलें।","इस बार अपने बाएँ हाथ और दाएँ पैर को ऊपर उठाते हुए, इस क्रिया को दोहराएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0805', 'Suspended Abdominal Fallout', 'waist', 'abs', '["obliques","hip flexors"]', 'body weight', 'strength', NULL, '["Attach a suspension trainer to a high anchor point and adjust the straps to waist height.","Stand facing away from the anchor point and hold the handles with your arms extended in front of you.","Lean forward at the waist, keeping your body straight and your core engaged.","Lower your body as far as you can while maintaining control and tension in your abs.","Pause for a moment at the bottom, then slowly raise your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक सस्पेंशन ट्रेनर को एक ऊंचे एंकर बिंदु पर संलग्न करें और पट्टियों को कमर की ऊंचाई के अनुसार समायोजित करें।","लंगर बिंदु से दूर की ओर मुंह करके खड़े हो जाएं और अपनी बाहों को अपने सामने फैलाकर हैंडल को पकड़ें।","अपने शरीर को सीधा और कोर को व्यस्त रखते हुए कमर के बल आगे की ओर झुकें।","अपने पेट पर नियंत्रण और तनाव बनाए रखते हुए अपने शरीर को जितना हो सके उतना नीचे झुकाएँ।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0806', 'Suspended Push-Up', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'body weight', 'strength', NULL, '["Find a suspension trainer and adjust it to an appropriate height.","Stand facing away from the anchor point and hold the handles with an overhand grip.","Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.","Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.","Push through your chest and arms to return to the starting position.","Repeat for the desired number of repetitions."]', '["एक सस्पेंशन ट्रेनर ढूंढें और उसे उचित ऊंचाई पर समायोजित करें।","एंकर पॉइंट से दूर की ओर मुंह करके खड़े हो जाएं और हैंडल को ओवरहैंड ग्रिप से पकड़ें।","अपने पैरों को आगे की ओर झुकाएं, अपने शरीर को आगे की ओर झुकाएं जब तक कि आपका वजन सस्पेंशन ट्रेनर द्वारा समर्थित न हो जाए।","अपने शरीर को सिर से एड़ी तक सीधा रखें, अपने कोर को संलग्न रखें और अपनी छाती को हैंडल की ओर नीचे करें।","प्रारंभिक स्थिति में लौटने के लिए अपनी छाती और भुजाओं पर दबाव डालें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0807', 'Suspended Reverse Crunch', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.","Pause for a moment at the top, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने घुटनों को अपनी छाती की ओर ऊपर उठाएं, अपने श्रोणि को अपनी पसलियों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने घुटनों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0808', 'Suspended Row', 'back', 'upper back', '["biceps","shoulders"]', 'body weight', 'strength', NULL, '["Set up a suspension trainer at an appropriate height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the handles with an overhand grip, palms facing each other.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]', '["उचित ऊंचाई पर सस्पेंशन ट्रेनर स्थापित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं।","हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों।","अपने शरीर को सीधा और अपनी एड़ियों को ज़मीन पर रखते हुए पीछे झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, अपनी छाती को हैंडल की ओर खींचें।","शीर्ष पर एक क्षण के लिए रुकें, फिर धीरे-धीरे अपने आप को प्रारंभिक स्थिति में वापस ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0809', 'Suspended Split Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand facing away from a suspension trainer with your feet shoulder-width apart.","Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.","Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए सस्पेंशन ट्रेनर से दूर की ओर मुंह करके खड़े हो जाएं।","एक पैर को आगे बढ़ाएं और अपने पैर के ऊपरी हिस्से को सस्पेंशन ट्रेनर के पैर के क्रैडल में रखें।","अपने खड़े पैर को मोड़ें और अपने शरीर को नीचे झुकाकर स्थिति में लाएँ, अपनी छाती को ऊपर रखें और अपने घुटने को अपने पैर की उंगलियों के अनुरूप रखें।","प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ी को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3433', 'Swimmer Kicks v. 2 (Male)', 'upper legs', 'glutes', '["hamstrings","quadriceps","calves"]', 'body weight', 'strength', NULL, '["Lie face down on a mat with your arms extended overhead.","Engage your core and lift your chest and legs off the ground simultaneously.","Kick your legs up and down in a fluttering motion, as if you were swimming.","Continue kicking for the desired number of repetitions.","Lower your chest and legs back down to the starting position."]', '["अपनी बाहों को ऊपर की ओर फैलाकर एक चटाई पर मुंह के बल लेट जाएं।","अपने कोर को संलग्न करें और अपनी छाती और पैरों को एक साथ जमीन से ऊपर उठाएं।","अपने पैरों को फड़फड़ाती गति से ऊपर-नीचे मारें, जैसे कि आप तैर रहे हों।","दोहराव की वांछित संख्या के लिए किक करना जारी रखें।","अपनी छाती और पैरों को वापस प्रारंभिक स्थिति में ले आएँ।"]', NULL, 8, 'sets', 0, 'opengym', 1),
('og-3318', 'Swing 360', 'cardio', 'cardiovascular system', '["shoulders","core"]', 'body weight', 'cardio', NULL, '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold your arms straight out in front of you, parallel to the ground.","Engage your core and swing your arms in a circular motion, rotating your torso as you do so.","Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.","Remember to breathe throughout the exercise."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","अपनी भुजाओं को अपने सामने सीधा, ज़मीन के समानांतर रखें।","अपने कोर को संलग्न करें और अपनी भुजाओं को गोलाकार गति में घुमाएँ, ऐसा करते समय अपने धड़ को घुमाएँ।","वांछित संख्या में दोहराव के लिए अपनी भुजाओं को घुमाते हुए और अपने धड़ को घुमाते हुए गोलाकार गति जारी रखें।","पूरे अभ्यास के दौरान सांस लेना याद रखें।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-1753', 'Three Bench Dip', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों से किनारे को पकड़कर, उँगलियाँ आगे की ओर करके बेंच पर बैठें।","अपने हाथों से अपने वजन को सहारा देते हुए, अपने बट को बेंच से स्लाइड करें।","अपनी कोहनियों को मोड़ें और अपने शरीर को तब तक नीचे करें जब तक कि आपकी ऊपरी भुजाएं जमीन के समानांतर न हो जाएं।","अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2459', 'Tire Flip', 'upper legs', 'glutes', '["hamstrings","quadriceps","core"]', 'tire', 'strength', NULL, '["Stand with your feet shoulder-width apart, facing the tire.","Bend your knees and hinge at the hips, lowering into a squat position.","Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.","Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.","As the tire flips over, use your upper body strength to guide it and maintain control.","Once the tire is fully flipped, quickly step back and reset your stance.","Repeat for the desired number of repetitions."]', '["टायर की ओर मुंह करके अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं।","अपने घुटनों को मोड़ें और कूल्हों पर टिकाएं, स्क्वाट स्थिति में आ जाएं।","नीचे पहुंचें और टायर के निचले किनारे को दोनों हाथों से पकड़ें, उंगलियां आपकी ओर हों।","अपने ग्लूट्स और पैर की मांसपेशियों को शामिल करें, और टायर को जमीन से ऊपर उठाने के लिए अपने पैरों के माध्यम से विस्फोटक रूप से ड्राइव करें।","जैसे ही टायर पलटता है, उसे निर्देशित करने और नियंत्रण बनाए रखने के लिए अपने शरीर के ऊपरी हिस्से की ताकत का उपयोग करें।","एक बार जब टायर पूरी तरह से पलट जाए, तो तुरंत पीछे हटें और अपना रुख दोबारा तय करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0811', 'Trap Bar Deadlift', 'upper legs', 'glutes', '["hamstrings","quadriceps","lower back"]', 'trap bar', 'strength', NULL, '["Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.","Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.","Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.","As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.","Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और ट्रैप बार आपके सामने जमीन पर हो।","अपने आप को नीचे लाने के लिए कूल्हों और घुटनों पर झुकें और ट्रैप बार के हैंडल को ओवरहैंड ग्रिप से पकड़ें।","जब आप अपने कूल्हों और घुटनों को फैलाकर ट्रैप बार को जमीन से ऊपर उठाना शुरू करें तो अपनी पीठ सीधी और छाती ऊपर रखें।","जैसे ही आप उठाते हैं, अपनी एड़ी के माध्यम से ड्राइविंग और आंदोलन के शीर्ष पर अपने ग्लूट्स को निचोड़ने पर ध्यान केंद्रित करें।","कूल्हों और घुटनों पर झुककर ट्रैप बार को वापस ज़मीन पर नीचे लाएँ, और पूरी गतिविधि के दौरान अपनी पीठ सीधी रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0814', 'Triceps Dip', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', 'beginner', '["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["किसी बेंच या कुर्सी के किनारे पर बैठें और अपने हाथों से किनारे को पकड़ें, उंगलियाँ आगे की ओर हों।","अपने हाथों से अपने वजन को सहारा देते हुए, अपने बट को बेंच से स्लाइड करें।","अपनी कोहनियों को मोड़ें और अपने शरीर को ज़मीन की ओर नीचे करें, अपनी पीठ को बेंच के पास रखें।","नीचे एक पल के लिए रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dips_-_Triceps_Version/0.jpg","Dips_-_Triceps_Version/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0812', 'Triceps Dip (Bench Leg)', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench, and straighten your arms.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["बेंच के किनारे पर बैठें और अपने हाथों से किनारे को पकड़ें, उंगलियाँ आगे की ओर हों।","अपने पैरों को आगे बढ़ाएं, अपने बट को बेंच से सरकाएं और अपनी बाहों को सीधा करें।","अपनी कोहनियों को मोड़ें और अपने शरीर को ज़मीन की ओर नीचे करें, अपनी पीठ को बेंच के पास रखें।","अपनी भुजाओं को सीधा करने के लिए अपनी हथेलियों से धक्का दें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0813', 'Triceps Dip (Between Benches)', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों से बेंच के किनारे को पकड़कर, उँगलियाँ आगे की ओर करके बेंच पर बैठें।","अपने हाथों से अपने वजन को सहारा देते हुए, अपने बट को बेंच से स्लाइड करें।","अपनी कोहनियों को मोड़ें और अपने शरीर को ज़मीन की ओर नीचे करें, अपनी पीठ को बेंच के पास रखें।","नीचे एक पल के लिए रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0815', 'Triceps Dips Floor', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.","Slide your butt off the front of the chair with your legs extended in front of you.","Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.","Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.","Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.","Repeat for the desired number of repetitions."]', '["कुर्सी या बेंच के किनारे पर अपने हाथों को अपने कूल्हों के पास रखकर बैठें, उंगलियाँ आगे की ओर हों।","अपने पैरों को अपने सामने फैलाते हुए अपने बट को कुर्सी के सामने से खिसकाएँ।","अपने ट्राइसेप्स और कोहनी के जोड़ों पर तनाव बनाए रखने के लिए अपनी कोहनियों को थोड़ा मोड़ते हुए अपनी भुजाओं को सीधा करें।","अपने शरीर को फर्श की ओर नीचे लाने के लिए धीरे-धीरे अपनी कोहनियों को मोड़ें जब तक कि आपकी कोहनियाँ लगभग 90 डिग्री के कोण पर न आ जाएँ।","एक बार जब आप गति के निचले स्तर पर पहुंच जाएं, तो अपनी कोहनियों को सीधा करने के लिए कुर्सी पर नीचे की ओर दबाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0816', 'Triceps Press', 'upper arms', 'triceps', '["shoulders"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground.","Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","अपनी भुजाओं को ज़मीन के समानांतर, अपने सामने सीधा फैलाएँ।","अपनी कोहनियों को मोड़ें और अपने शरीर को ज़मीन की ओर नीचे करें, अपनी ऊपरी भुजाओं को अपनी भुजाओं के पास रखें।","नीचे एक पल के लिए रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0817', 'Triceps Stretch', 'upper arms', 'triceps', '["shoulders"]', 'body weight', 'strength', NULL, '["Stand or sit upright with your back straight.","Extend one arm overhead, bending it at the elbow.","Place your opposite hand on the bent elbow and gently pull it towards your head.","Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.","Release the stretch and repeat on the other arm."]', '["अपनी पीठ सीधी करके सीधे खड़े हों या बैठें।","एक हाथ को कोहनी पर मोड़ते हुए ऊपर की ओर फैलाएँ।","अपने उल्टे हाथ को मुड़ी हुई कोहनी पर रखें और धीरे से उसे अपने सिर की ओर खींचें।","अपने ट्राइसेप्स में हल्का खिंचाव महसूस करते हुए 15-30 सेकंड तक खिंचाव बनाए रखें।","खिंचाव छोड़ें और दूसरी बांह पर दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0871', 'Tuck Crunch', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.","Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को जोड़ते हुए, अपने कंधे के ब्लेड को जमीन से ऊपर उठाएं और अपने घुटनों को अपनी छाती की ओर लाएं, साथ ही अपने ऊपरी शरीर को अपने घुटनों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कंधे के ब्लेड को नीचे लाएं और अपने पैरों को वापस प्रारंभिक स्थिति में फैलाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Tuck_Crunch/0.jpg","Tuck_Crunch/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0818', 'Twin Handle Parallel Grip Lat Pulldown', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'cable', 'strength', NULL, '["Adjust the seat height and position yourself facing the cable machine.","Grasp the handles with an overhand grip, hands shoulder-width apart.","Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.","Lean back slightly and keep your chest up, maintaining a neutral spine.","Pull the handles down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें और अपने आप को केबल मशीन के सामने रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से अलग रखें।","बैठ जाएं और अपनी जांघों को जांघ पैड के नीचे रखें, अपने पैरों को फर्श पर सपाट रखें।","थोड़ा पीछे झुकें और अपनी छाती को ऊपर रखें, रीढ़ की हड्डी को तटस्थ बनाए रखें।","अपने कंधे के ब्लेड को एक साथ दबाते हुए, हैंडल को अपनी ऊपरी छाती की ओर नीचे खींचें।","गति के निचले भाग में एक पल के लिए रुकें, अपने लैट्स में संकुचन महसूस करें।","धीरे-धीरे हैंडल को छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1466', 'Twist Hip Lift', 'upper legs', 'glutes', '["obliques","hamstrings"]', 'body weight', 'strength', NULL, '["Lie on your back with your knees bent and feet flat on the ground.","Place your hands by your sides for support.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.","Return to the starting position and repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेटें।","समर्थन के लिए अपने हाथों को अपने बगल में रखें।","अपने ग्लूट्स को संलग्न करें और अपने कूल्हों को ज़मीन से ऊपर उठाएं, जिससे आपके घुटनों से लेकर आपके कंधों तक एक सीधी रेखा बन जाए।","अपने कूल्हों को ऊपर उठाते हुए, अपने निचले शरीर को दाहिनी ओर मोड़ें, अपने घुटनों को ज़मीन की ओर लाएँ।","प्रारंभिक स्थिति पर लौटें और बाईं ओर मोड़ को दोहराएं।","पुनरावृत्ति की वांछित संख्या के लिए बारी-बारी से मोड़ जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2802', 'Twisted Leg Raise', 'waist', 'abs', '["obliques","hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift both legs off the ground, keeping them straight.","As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर अपनी पीठ के बल सीधे लेट जाएँ।","समर्थन के लिए अपने हाथों को अपने ग्लूट्स के नीचे रखें।","अपने पेट को संलग्न करें और दोनों पैरों को सीधा रखते हुए जमीन से ऊपर उठाएं।","जैसे ही आप अपने पैर उठाते हैं, अपने कूल्हों को एक तरफ मोड़ें, अपने पैरों को अपने विपरीत कंधे की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","इस क्रिया को दोहराएँ, इस बार अपने कूल्हों को दूसरी ओर मोड़ें।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2801', 'Twisted Leg Raise (Female)', 'waist', 'abs', '["obliques","hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and lift your legs off the ground, bringing them towards your chest.","As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर अपनी पीठ के बल सीधे लेट जाएँ।","अपने घुटनों को मोड़ें और अपने पैरों को जमीन से ऊपर उठाएं, उन्हें अपनी छाती की ओर लाएं।","जैसे ही आप अपने पैर उठाते हैं, अपने कूल्हों को एक तरफ मोड़ें, अपने घुटनों को अपने विपरीत कंधे की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","इस क्रिया को दोहराएँ, इस बार अपने कूल्हों को दूसरी ओर मोड़ें।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3231', 'Two Toe Touch (Male)', 'back', 'spine', '["hamstrings","glutes"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your arms extended out to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with both hands, keeping your legs straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी भुजाएं बगल की तरफ फैला लें।","अपनी पीठ सीधी और घुटने थोड़े मुड़े हुए रखते हुए कमर के बल आगे की ओर झुकें।","अपने पैरों को सीधा रखते हुए, दोनों हाथों से अपने पैर की उंगलियों तक पहुंचें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1365', 'Upper Back Stretch', 'back', 'upper back', '["shoulders"]', 'body weight', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart.","Extend your arms straight in front of you, parallel to the ground.","Interlace your fingers and rotate your palms away from your body.","Slowly raise your arms overhead, keeping them straight and parallel to each other.","As you raise your arms, squeeze your shoulder blades together.","Hold the stretch for 15-30 seconds, then release and repeat."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं।","अपनी भुजाओं को ज़मीन के समानांतर, अपने सामने सीधा फैलाएँ।","अपनी उंगलियों को आपस में मिलाएं और अपनी हथेलियों को अपने शरीर से दूर घुमाएं।","अपनी भुजाओं को धीरे-धीरे ऊपर उठाएं, उन्हें सीधा और एक-दूसरे के समानांतर रखें।","जैसे ही आप अपनी भुजाएं ऊपर उठाएं, अपने कंधे के ब्लेड को एक साथ दबाएं।","15-30 सेकंड के लिए खिंचाव को रोककर रखें, फिर छोड़ें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1366', 'Upward Facing Dog', 'back', 'spine', '["shoulders","chest"]', 'body weight', 'strength', NULL, '["Lie face down on the floor with your legs extended behind you.","Place your hands on the floor next to your lower ribs, fingers pointing forward.","Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.","Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.","Hold this position for a few breaths, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को अपने पीछे फैलाकर फर्श पर मुंह करके लेट जाएं।","अपने हाथों को अपनी निचली पसलियों के बगल में फर्श पर रखें, उंगलियां आगे की ओर हों।","अपने हाथों को फर्श पर मजबूती से दबाएं और अपनी बाहों को सीधा करें, अपने धड़ और जांघों को जमीन से ऊपर उठाएं।","अपने कंधों को पीछे और नीचे घुमाएँ, अपनी छाती खोलें और अपनी निगाहें छत की ओर उठाएँ।","कुछ सांसों के लिए इस स्थिति में रहें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3420', 'V-Sit On Floor', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Sit on the floor with your legs extended in front of you.","Lean back slightly and lift your legs off the ground, keeping them straight.","Simultaneously, lift your upper body off the ground and reach your arms towards your legs.","Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को अपने सामने फैलाकर फर्श पर बैठें।","थोड़ा पीछे झुकें और अपने पैरों को सीधा रखते हुए जमीन से ऊपर उठाएं।","इसके साथ ही, अपने ऊपरी शरीर को जमीन से ऊपर उठाएं और अपनी भुजाओं को अपने पैरों की ओर ले जाएं।","कुछ सेकंड के लिए इस स्थिति में रहें, फिर धीरे-धीरे अपने ऊपरी शरीर और पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0826', 'Vertical Leg Raise (On Parallel Bars)', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Hang from the parallel bars with your arms fully extended and your body straight.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी भुजाओं को पूरी तरह फैलाकर और अपने शरीर को सीधा रखते हुए समानांतर सलाखों से लटकें।","अपने कोर को संलग्न करें और अपने पैरों को अपने सामने ऊपर उठाएं, उन्हें सीधा रखें।","तब तक उठाना जारी रखें जब तक कि आपके पैर जमीन के समानांतर या थोड़ा ऊंचे न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2141', 'Walk Elliptical Cross Trainer', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","glutes","calves"]', 'elliptical machine', 'cardio', NULL, '["Adjust the resistance level and incline of the elliptical machine to your desired settings.","Step onto the pedals of the machine and grip the handles lightly.","Begin by pushing down with your feet and pulling the handles towards your body.","Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.","Maintain a steady pace and keep your core engaged throughout the exercise.","Continue for the desired duration of your cardio workout.","Gradually decrease the intensity and speed of the machine before stepping off."]', '["अण्डाकार मशीन के प्रतिरोध स्तर और झुकाव को अपनी इच्छित सेटिंग्स पर समायोजित करें।","मशीन के पैडल पर चढ़ें और हैंडल को हल्के से पकड़ें।","अपने पैरों से नीचे की ओर दबाव डालकर और हैंडल को अपने शरीर की ओर खींचकर शुरुआत करें।","चलने या दौड़ने की गति का अनुकरण करने के लिए, धक्का देने और खींचने के बीच बारी-बारी से इस गति को जारी रखें।","एक स्थिर गति बनाए रखें और पूरे अभ्यास के दौरान अपने कोर को व्यस्त रखें।","अपने कार्डियो वर्कआउट की वांछित अवधि तक जारी रखें।","उतरने से पहले मशीन की तीव्रता और गति को धीरे-धीरे कम करें।"]', NULL, 3.5, 'time', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-3655', 'Walking High Knees Lunge', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","glutes","calves"]', 'body weight', 'cardio', NULL, '["Stand with your feet hip-width apart.","Lift your right knee up towards your chest as high as you can while balancing on your left leg.","Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.","Push off with your right foot and bring your left knee up towards your chest.","Step forward with your left foot and lower your body into a lunge position.","Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े रहें।","अपने बाएं पैर पर संतुलन बनाते हुए अपने दाहिने घुटने को अपनी छाती की ओर जितना हो सके ऊपर उठाएं।","अपने दाहिने पैर के साथ आगे बढ़ें और अपने शरीर को नीचे झुकें, दोनों घुटनों को 90 डिग्री के कोण पर झुकाएँ।","अपने दाहिने पैर से धक्का दें और अपने बाएँ घुटने को अपनी छाती की ओर ऊपर लाएँ।","अपने बाएं पैर के साथ आगे बढ़ें और अपने शरीर को लूंज स्थिति में नीचे लाएं।","पैरों को बारी-बारी से मोड़ना और आगे की ओर झुकना जारी रखें, अपने कोर को व्यस्त रखें और स्थिर गति बनाए रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 3.5, 'time', 0, 'opengym', 1),
('og-1460', 'Walking Lunge', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Take a step forward with your right leg, lowering your body into a lunge position.","Keep your torso upright and your front knee aligned with your ankle.","Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.","Continue alternating legs and walking forward, maintaining a controlled and steady pace.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने दाहिने पैर के साथ एक कदम आगे बढ़ाएं, अपने शरीर को लूंज स्थिति में नीचे लाएं।","अपने धड़ को सीधा रखें और अपने सामने के घुटने को अपने टखने के साथ संरेखित रखें।","अपने दाहिने पैर से धक्का दें और अपने बाएं पैर को आगे लाएं, अपने बाएं पैर के साथ एक लंज स्थिति में आ जाएं।","नियंत्रित और स्थिर गति बनाए रखते हुए पैरों को बारी-बारी से बदलना और आगे बढ़ना जारी रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 3.5, 'sets', 0, 'opengym', 1),
('og-3666', 'Walking On Incline Treadmill', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'leverage machine', 'cardio', NULL, '["Adjust the incline level on the treadmill to your desired intensity.","Stand on the treadmill with your feet shoulder-width apart.","Start walking at a comfortable pace, ensuring that you maintain proper form.","Engage your core muscles and keep your back straight throughout the exercise.","Continue walking on the incline treadmill for the desired duration of your cardio workout.","Gradually decrease the incline and speed of the treadmill to cool down before stopping."]', '["ट्रेडमिल पर झुकाव स्तर को अपनी वांछित तीव्रता के अनुसार समायोजित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए ट्रेडमिल पर खड़े हो जाएं।","आरामदायक गति से चलना शुरू करें, यह सुनिश्चित करते हुए कि आप उचित फॉर्म बनाए रखें।","अपनी मुख्य मांसपेशियों को शामिल करें और पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें।","अपने कार्डियो वर्कआउट की वांछित अवधि के लिए इनक्लाइन ट्रेडमिल पर चलना जारी रखें।","रुकने से पहले ठंडा होने के लिए ट्रेडमिल का झुकाव और गति धीरे-धीरे कम करें।"]', NULL, 3.5, 'time', 0, 'opengym', 1),
('og-2311', 'Walking On Stepmill', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","glutes","calves"]', 'stepmill machine', 'cardio', NULL, '["Adjust the stepmill machine to a comfortable level.","Step onto the machine and place your hands on the handrails for support.","Start walking by placing one foot on a step and then the other, alternating between legs.","Maintain an upright posture and engage your core muscles.","Continue walking for the desired duration or distance.","Gradually increase the intensity or speed as you become more comfortable with the exercise.","Remember to cool down and stretch after completing the exercise."]', '["स्टेपमिल मशीन को आरामदायक स्तर पर समायोजित करें।","मशीन पर कदम रखें और सहारे के लिए अपने हाथों को रेलिंग पर रखें।","एक पैर को एक सीढ़ी पर और फिर दूसरे को, पैरों के बीच बारी-बारी से रखकर चलना शुरू करें।","सीधी मुद्रा बनाए रखें और अपनी मुख्य मांसपेशियों को शामिल करें।","वांछित अवधि या दूरी तक चलते रहें।","जैसे-जैसे आप व्यायाम के साथ अधिक सहज होते जाएं, धीरे-धीरे तीव्रता या गति बढ़ाएं।","व्यायाम पूरा करने के बाद ठंडा होना और स्ट्रेच करना याद रखें।"]', NULL, 3.5, 'time', 0, 'opengym', 1),
('og-0830', 'Weighted Bench Dip', 'upper arms', 'triceps', '["chest","shoulders"]', 'weighted', 'strength', NULL, '["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपने हाथों से किनारे को पकड़कर, उँगलियाँ आगे की ओर करके बेंच पर बैठें।","अपने हाथों से अपने वजन को सहारा देते हुए, अपने बट को बेंच से स्लाइड करें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ फर्श के समानांतर न हो जाएँ।","अपनी भुजाओं को सीधा करके स्वयं को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2987', 'Weighted Close Grip Chin-Up On Dip Cage', 'back', 'lats', '["biceps","forearms"]', 'weighted', 'strength', NULL, '["Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.","Hang from the bars with your arms fully extended, feet off the ground, and body straight.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.","Continue pulling until your chin is above the bars, then pause for a moment.","Slowly lower your body back down to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["डिप केज के सामने खड़े हो जाएं और समानांतर पट्टियों को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से अलग हों।","अपनी बाहों को पूरी तरह फैलाकर, पैर ज़मीन से ऊपर और शरीर सीधा करके सलाखों से लटकें।","अपनी पीठ की मांसपेशियों को संलग्न करें और अपने शरीर को सलाखों की ओर ऊपर खींचें, अपनी कोहनियों को अपनी तरफ से पास रखें।","तब तक खींचते रहें जब तक आपकी ठुड्डी सलाखों से ऊपर न आ जाए, फिर एक पल के लिए रुकें।","अपनी बाहों को पूरी तरह फैलाते हुए धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3643', 'Weighted Cossack Squats (Male)', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'weighted', 'strength', NULL, '["Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.","Hold a weight in front of your chest with both hands.","Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.","Go as low as you can while maintaining balance and keeping your chest up.","Push through the heel of the bent leg to return to the starting position.","Repeat on the other side, alternating between legs."]', '["अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके और पंजों की उंगलियों को थोड़ा बाहर की ओर करके खड़े रहें।","दोनों हाथों से अपनी छाती के सामने एक वजन पकड़ें।","अपने वजन को एक तरफ शिफ्ट करें और जिस तरफ आप शिफ्ट हुए हैं उस तरफ के घुटने को मोड़कर अपने शरीर को नीचे लाएं, जबकि दूसरे पैर को सीधा रखें।","संतुलन बनाए रखते हुए और अपनी छाती को ऊपर रखते हुए जितना हो सके उतना नीचे जाएं।","प्रारंभिक स्थिति में लौटने के लिए मुड़े हुए पैर की एड़ी से धक्का दें।","पैरों के बीच बारी-बारी से दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0832', 'Weighted Crunch', 'waist', 'abs', '["obliques"]', 'weighted', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Hold a weight plate or dumbbell on your chest.","Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपनी छाती पर वेट प्लेट या डम्बल पकड़ें।","अपने पेट को संलग्न करें और अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपके कंधे के ब्लेड जमीन से ऊपर न आ जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3670', 'Weighted Decline Sit-Up', 'waist', 'abs', '["hip flexors","lower back"]', 'weighted', 'strength', NULL, '["Lie flat on a decline bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फ़ुट पैड के नीचे सुरक्षित रखते हुए डिक्लाइन बेंच पर सीधे लेट जाएँ।","अपने हाथों को अपने सिर के पीछे या अपनी छाती के पार रखें।","अपने पेट को संलग्न करें और धीरे-धीरे अपने ऊपरी शरीर को बेंच से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ जमीन से लंबवत न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0833', 'Weighted Donkey Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'weighted', 'strength', NULL, '["Stand on a raised platform with your toes on the edge and your heels hanging off.","Hold onto a stable object for support.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैर की उंगलियों को किनारे पर और अपनी एड़ियों को लटकाकर एक ऊंचे मंच पर खड़े हो जाएं।","समर्थन के लिए किसी स्थिर वस्तु को पकड़ें।","अपनी एड़ियों को फैलाकर जितना हो सके अपनी एड़ियों को ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1310', 'Weighted Drop Push Up', 'chest', 'pectorals', '["triceps","shoulders"]', 'weighted', 'strength', NULL, '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.","As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.","Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.","Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.","Continue alternating between the wider and narrower hand positions for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा और अपने पैरों को एक साथ मिलाकर एक ऊंचे तख़्ते की स्थिति से शुरुआत करें।","अपनी कोहनियों को अपने शरीर के पास रखते हुए, अपनी छाती को ज़मीन की ओर झुकाएँ।","एक बार जब आपकी छाती जमीन से ठीक ऊपर हो जाए, तो अपने हाथों को जमीन से ऊपर उठाते हुए खुद को ऊपर की ओर धकेलें।","जैसे ही आप ऊपर की ओर धकेलते हैं, तेजी से अपने हाथों को बगल की ओर और थोड़ा आगे की ओर ले जाएं, जिससे आपका शरीर जमीन की ओर गिर जाए।","अपने हाथों को व्यापक स्थिति में पकड़ें और तुरंत अपनी छाती को फिर से जमीन की ओर झुकाएँ।","पुश-अप गति को दोहराएं, नीचे गिरें और अपने हाथों से खुद को संकरी स्थिति में पकड़ें।","दोहराव की वांछित संख्या के लिए हाथों की चौड़ी और संकरी स्थितियों के बीच बारी-बारी से काम करना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2135', 'Weighted Front Plank', 'waist', 'abs', '["shoulders","lower back"]', 'weighted', 'strength', NULL, '["Start by lying face down on the floor.","Place your forearms on the ground, with your elbows directly under your shoulders.","Extend your legs straight out behind you, with your toes on the ground.","Engage your core and lift your body off the ground, balancing on your forearms and toes.","Keep your body in a straight line from your head to your heels.","Hold this position for the desired amount of time.","Lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["फर्श पर मुंह के बल लेटकर शुरुआत करें।","अपने अग्रबाहुओं को ज़मीन पर रखें, अपनी कोहनियों को सीधे अपने कंधों के नीचे रखें।","अपने पैरों को अपने पीछे सीधा फैलाएं, अपने पंजों की उंगलियों को ज़मीन पर रखें।","अपने कोर को संलग्न करें और अपने अग्र-भुजाओं और पैर की उंगलियों पर संतुलन बनाते हुए अपने शरीर को जमीन से ऊपर उठाएं।","अपने शरीर को सिर से एड़ी तक एक सीधी रेखा में रखें।","वांछित समय तक इस स्थिति में रहें।","अपने शरीर को वापस प्रारंभिक स्थिति में ले आएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0834', 'Weighted Front Raise', 'shoulders', 'delts', '["biceps","forearms"]', 'weighted', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल पकड़ें और अपनी हथेलियों को अपनी जांघों की ओर रखें।","अपनी बाहों को सीधा रखते हुए, सांस छोड़ें और डम्बल को अपने सामने तब तक उठाएं जब तक वे कंधे के स्तर पर न आ जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0866', 'Weighted Hanging Leg-Hip Raise', 'waist', 'abs', '["hip flexors","lower back"]', 'weighted', 'strength', NULL, '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने पैरों को अपने सामने ऊपर उठाएं, उन्हें सीधा रखें।","तब तक उठाना जारी रखें जब तक कि आपके पैर जमीन के समानांतर या थोड़ा ऊंचे न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0835', 'Weighted Hyperextension (On Stability Ball)', 'back', 'spine', '["glutes","hamstrings"]', 'weighted', 'strength', NULL, '["Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने आप को एक स्थिरता वाली गेंद पर नीचे की ओर मुंह करके रखें, अपने कूल्हों को गेंद पर टिकाएं और स्थिरता के लिए अपने पैरों को दीवार पर टिकाएं।","अपने हाथों को अपने सिर के पीछे रखें या उन्हें अपनी छाती के ऊपर से पार करें।","अपने कोर को संलग्न करें और धीरे-धीरे अपने ऊपरी शरीर को गेंद से ऊपर उठाएं, अपनी पीठ को तब तक फैलाएं जब तक कि आपका शरीर एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3641', 'Weighted Kneeling Step With Swing', 'shoulders', 'delts', '["triceps","core"]', 'weighted', 'strength', NULL, '["Start in a kneeling position with your knees hip-width apart and your back straight.","Hold a weight in each hand, with your arms extended straight down in front of you.","Engage your core and swing the weights up and overhead, keeping your arms straight.","Lower the weights back down to the starting position and repeat for the desired number of repetitions."]', '["अपने घुटनों को कूल्हे की चौड़ाई के बराबर दूरी पर और अपनी पीठ को सीधा रखते हुए घुटनों के बल बैठने की स्थिति से शुरुआत करें।","प्रत्येक हाथ में एक वज़न पकड़ें, अपनी भुजाएँ अपने सामने सीधी नीचे की ओर फैलाएँ।","अपने कोर को संलग्न करें और अपनी भुजाओं को सीधा रखते हुए वजन को ऊपर और ऊपर की ओर झुकाएँ।","वजन को वापस प्रारंभिक स्थिति में कम करें और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3644', 'Weighted Lunge With Swing', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'weighted', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a weight in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, swing the weights forward and upward, keeping your arms straight.","Push off with your right foot and return to the starting position, swinging the weights back down.","Repeat with your left foot and continue alternating legs for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में वजन पकड़ें।","अपने दाहिने पैर से एक कदम आगे बढ़ाएं, अपने शरीर को नीचे झुकाकर स्थिति में लाएं।","जैसे ही आप आगे बढ़ते हैं, अपनी बाहों को सीधा रखते हुए वजन को आगे और ऊपर की ओर झुकाएं।","अपने दाहिने पैर से धक्का दें और वज़न को वापस नीचे झुकाते हुए प्रारंभिक स्थिति में लौट आएं।","अपने बाएं पैर से दोहराएं और वांछित संख्या में दोहराव के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3286', 'Weighted Muscle Up', 'back', 'lats', '["biceps","triceps","shoulders","chest"]', 'weighted', 'strength', NULL, '["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest reaches the bar, then pause for a moment.","Slowly lower yourself back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को अपने से दूर की ओर रखते हुए पुल-अप बार से लटकने से शुरुआत करें और आपके हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपने कोर को संलग्न करें और अपने शरीर को अपनी छाती की ओर ले जाते हुए बार की ओर ऊपर खींचें।","जैसे ही आप गति के शीर्ष पर पहुँचते हैं, अपनी पकड़ को बदलें ताकि आपकी हथेलियाँ आपकी ओर हों।","जब तक आपकी छाती बार तक न पहुंच जाए, तब तक खुद को ऊपर खींचते रहें, फिर एक पल के लिए रुकें।","पूरे आंदोलन पर नियंत्रण बनाए रखते हुए, धीरे-धीरे अपने आप को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3312', 'Weighted Muscle Up (On Bar)', 'back', 'lats', '["biceps","triceps","shoulders","forearms"]', 'weighted', 'strength', NULL, '["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your elbows and pull your chest towards the bar, keeping your body straight.","Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को अपने से दूर की ओर रखते हुए पुल-अप बार से लटकने से शुरुआत करें और आपके हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को नीचे और पीछे खींचें।","अपनी कोहनियों को मोड़ें और अपने शरीर को सीधा रखते हुए अपनी छाती को बार की ओर खींचें।","एक बार जब आपकी छाती बार तक पहुंच जाए, तो अपने हाथों से नीचे की ओर धकेलें और अपनी कोहनियों को पीछे ले जाएं, अपने शरीर को बार से ऊपर उठाएं।","गति के शीर्ष पर रुकें, फिर धीरे-धीरे अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3290', 'Weighted One Hand Pull Up', 'back', 'lats', '["biceps","forearms"]', 'weighted', 'strength', NULL, '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arm fully extended and your body straight.","Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]', '["पुल-अप बार को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी बांह पूरी तरह फैलाकर और शरीर सीधा करके बार से लटकें।","अपने कोर को संलग्न करें और अपनी कोहनी को मोड़कर और अपनी पीठ की मांसपेशियों को निचोड़कर अपने शरीर को बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","नियंत्रण के साथ अपने शरीर को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0840', 'Weighted Overhead Crunch (On Stability Ball)', 'waist', 'abs', '["obliques","lower back"]', 'weighted', 'strength', NULL, '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands and extend your arms overhead.","Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your torso back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर एक स्टेबिलिटी बॉल पर बैठें।","दोनों हाथों से वेट प्लेट या डम्बल पकड़ें और अपनी बाहों को ऊपर की ओर फैलाएँ।","अपने पेट को संलग्न करें और धीरे-धीरे अपने धड़ को आगे की ओर मोड़ें, अपनी छाती को अपने घुटनों की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने धड़ को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0841', 'Weighted Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'weighted', 'strength', NULL, '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["पुल-अप बार को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को सीधा करके बार से लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए अपने शरीर को बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0844', 'Weighted Round Arm', 'shoulders', 'delts', '["triceps","upper back"]', 'weighted', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows.","Continue lifting your arms until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी कोहनियों को हल्का सा मोड़ते हुए, अपनी भुजाओं को बगल की ओर उठाएँ।","अपनी भुजाओं को तब तक उठाते रहें जब तक वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0846', 'Weighted Russian Twist', 'waist', 'abs', '["obliques","lower back"]', 'weighted', 'strength', NULL, '["Sit on the ground with your knees bent and your feet flat on the floor.","Hold a weight or medicine ball with both hands in front of your chest.","Lean back slightly, keeping your back straight and your core engaged.","Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और अपने पैरों को फर्श पर सपाट करके जमीन पर बैठें।","अपनी छाती के सामने दोनों हाथों से कोई वज़न या दवा की गेंद पकड़ें।","अपनी पीठ सीधी और अपने कोर को व्यस्त रखते हुए थोड़ा पीछे झुकें।","धीरे-धीरे अपने धड़ को दाहिनी ओर मोड़ें, वजन या दवा की गेंद को अपनी दाहिनी ओर फर्श की ओर लाएँ।","एक पल के लिए रुकें, फिर अपने धड़ को बाईं ओर मोड़ें, वजन या दवा की गेंद को अपनी बाईं ओर फर्श की ओर लाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0845', 'Weighted Russian Twist (Legs Up)', 'waist', 'abs', '["obliques","hip flexors"]', 'weighted', 'strength', NULL, '["Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.","Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the ground on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को जमीन से ऊपर उठाकर जमीन पर बैठें, अपने पैरों को एक साथ रखें।","अपनी कोहनियों को थोड़ा मोड़कर, दोनों हाथों से वजन को अपनी छाती के सामने रखें।","अपनी मुख्य मांसपेशियों को जोड़ने के लिए थोड़ा पीछे झुकें।","अपने धड़ को दाहिनी ओर मोड़ें, वजन को अपनी दाहिनी ओर जमीन की ओर लाएं।","एक पल के लिए रुकें, फिर अपने धड़ को बाईं ओर मोड़ें, जिससे वजन आपकी बाईं ओर जमीन की ओर आए।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-2371', 'Weighted Russian Twist v. 2', 'waist', 'abs', '["obliques","lower back"]', 'weighted', 'strength', NULL, '["Sit on the ground with your knees bent and feet flat on the floor.","Hold the weight with both hands in front of your chest.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को फर्श पर सपाट करके जमीन पर बैठें।","दोनों हाथों से वजन को अपनी छाती के सामने रखें।","अपनी मुख्य मांसपेशियों को जोड़ने के लिए थोड़ा पीछे झुकें।","अपने धड़ को दाईं ओर मोड़ें, वजन को अपने शरीर के दाईं ओर लाएं।","एक पल के लिए रुकें, फिर अपने धड़ को बाईं ओर मोड़ें, जिससे वजन आपके शरीर के बाईं ओर आ जाए।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0847', 'Weighted Seated Bicep Curl (On Stability Ball)', 'upper arms', 'biceps', '["forearms"]', 'medicine ball', 'strength', NULL, '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.","Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the medicine ball back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक स्टेबिलिटी बॉल पर बैठें।","दवा की गेंद को हाथ से पकड़ें, हथेलियाँ ऊपर की ओर हों और अपनी भुजाओं को बगल में लटका दें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और मेडिसिन बॉल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","साँस लें और धीरे-धीरे दवा की गेंद को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0849', 'Weighted Seated Twist (On Stability Ball)', 'waist', 'abs', '["obliques","lower back"]', 'weighted', 'strength', NULL, '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands close to your chest.","Engage your core and slowly rotate your torso to one side, keeping your hips stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर एक स्टेबिलिटी बॉल पर बैठें।","दोनों हाथों से अपनी छाती के पास वेट प्लेट या डम्बल पकड़ें।","अपने कोर को संलग्न करें और अपने कूल्हों को स्थिर रखते हुए धीरे-धीरे अपने धड़ को एक तरफ घुमाएँ।","घूर्णन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दूसरी ओर भी घुमाएँ दोहराएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0850', 'Weighted Side Bend (On Stability Ball)', 'waist', 'abs', '["obliques","lower back"]', 'weighted', 'strength', NULL, '["Sit on a stability ball with your feet shoulder-width apart and flat on the ground.","Hold a weight in one hand and place your other hand on your hip.","Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई से अलग और जमीन पर सपाट रखकर एक स्टेबिलिटी बॉल पर बैठें।","एक हाथ में वजन पकड़ें और दूसरे हाथ को अपने कूल्हे पर रखें।","अपने कोर को संलग्न करें और अपनी पीठ को सीधा रखते हुए धीरे-धीरे भार वाले हिस्से की ओर झुकें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0851', 'Weighted Sissy Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'weighted', 'strength', NULL, '["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold a weight in front of your chest with both hands, or place a barbell across your upper back.","Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके पैर की उंगलियां थोड़ी बाहर की ओर हों।","दोनों हाथों से अपनी छाती के सामने वजन पकड़ें, या अपनी ऊपरी पीठ पर एक बारबेल रखें।","अपनी छाती को ऊपर और अपने कोर को व्यस्त रखते हुए, घुटनों और कूल्हों पर झुकते हुए धीरे-धीरे अपने शरीर को नीचे लाएँ।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें जमीन के समानांतर न हो जाएं या जितना नीचे आप आराम से जा सकें, उतना नीचे आ जाएं।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0852', 'Weighted Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'weighted', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold a weight in front of your chest or on your shoulders.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Push through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपनी छाती के सामने या अपने कंधों पर कोई वजन रखें।","अपने कोर को संलग्न करें और अपने कूल्हों को नीचे और पीछे करते समय अपनी छाती को ऊपर रखें, जैसे कि एक कुर्सी पर बैठे हों।","तब तक नीचे जाएँ जब तक आपकी जाँघें ज़मीन के समानांतर न हो जाएँ, या जितना नीचे आप आराम से जा सकें।","वापस खड़े होने के लिए अपनी एड़ियों को ऊपर से दबाएं, अपने ग्लूट्स को ऊपर से दबाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0853', 'Weighted Standing Curl', 'upper arms', 'biceps', '["forearms"]', 'weighted', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.","Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों में डंबल पकड़ लें, हथेलियां आगे की ओर हों।","अपनी कोहनियों को अपने धड़ के पास रखें और वजन को कंधे के स्तर तक मोड़ते हुए सांस छोड़ें।","शीर्ष पर एक क्षण के लिए रुकें, फिर श्वास लेते हुए धीरे-धीरे वजन को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0854', 'Weighted Standing Hand Squeeze', 'lower arms', 'forearms', '["biceps","triceps"]', 'weighted', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a weight in each hand.","Extend your arms straight in front of you, palms facing each other.","Squeeze your hands together as hard as you can, engaging your forearms.","Hold the squeeze for a few seconds, then release.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में वजन पकड़ लें।","अपनी बाहों को अपने सामने सीधा फैलाएं, हथेलियाँ एक-दूसरे के सामने हों।","जितना हो सके अपने हाथों को एक साथ निचोड़ें, अपने अग्रबाहुओं को जोड़ते हुए।","कुछ सेकंड के लिए निचोड़ को रोककर रखें, फिर छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3313', 'Weighted Straight Bar Dip', 'chest', 'pectorals', '["triceps","shoulders"]', 'weighted', 'strength', NULL, '["Position yourself between parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपनी भुजाओं को पूरी तरह फैलाकर और अपने शरीर को सीधा रखते हुए अपने आप को समानांतर सलाखों के बीच रखें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ ज़मीन के समानांतर न हो जाएँ।","एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3642', 'Weighted Stretch Lunge', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'weighted', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Take a step forward with your right foot, keeping your back straight.","Lower your body by bending your knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपनी पीठ सीधी रखते हुए अपने दाहिने पैर से एक कदम आगे बढ़ाएं।","अपने घुटनों को मोड़कर अपने शरीर को तब तक नीचे करें जब तक कि आपकी दाहिनी जांघ जमीन के समानांतर न हो जाए।","प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी को धक्का दें।","अपने बाएँ पैर से दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0856', 'Weighted Svend Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'weighted', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.","Keep your elbows slightly bent and your palms facing each other.","Press the weight plate straight out in front of you, fully extending your arms.","Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों से अपनी छाती के सामने एक वेट प्लेट पकड़ लें।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखें और अपनी हथेलियों को एक-दूसरे के सामने रखें।","अपनी भुजाओं को पूरी तरह फैलाते हुए वेट प्लेट को सीधे अपने सामने दबाएं।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे वेट प्लेट को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1754', 'Weighted Three Bench Dips', 'upper arms', 'triceps', '["chest","shoulders"]', 'weighted', 'strength', NULL, '["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.","Lower your body by bending your elbows, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["बेंच के किनारे पर बैठें और अपने हाथों से किनारे को पकड़ें, उंगलियाँ आगे की ओर हों।","अपने पैरों को आगे की ओर बढ़ाएं, अपने बट को बेंच से सरकाएं और अपनी भुजाओं से अपने वजन को सहारा दें।","अपनी कोहनियों को मोड़कर, अपनी पीठ को बेंच के पास रखते हुए अपने शरीर को नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1755', 'Weighted Tricep Dips', 'upper arms', 'triceps', '["chest","shoulders"]', 'weighted', 'strength', NULL, '["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the front of the bench with your legs extended in front of you.","Keep your back close to the bench and your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["किसी बेंच या कुर्सी के किनारे पर अपने हाथों से अपने कूल्हों के बगल वाले किनारे को पकड़कर बैठें।","अपने पैरों को अपने सामने फैलाकर अपने बट को बेंच के सामने से खिसकाएँ।","अपनी पीठ को बेंच के पास रखें और अपनी कोहनियाँ थोड़ी मुड़ी हुई हों।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ फर्श के समानांतर न हो जाएँ।","अपनी भुजाओं को सीधा करके स्वयं को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1767', 'Weighted Triceps Dip On High Parallel Bars', 'upper arms', 'triceps', '["chest","shoulders"]', 'weighted', 'strength', NULL, '["Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने आप को दो समानांतर सलाखों के बीच रखें, अपने हाथों से सलाखों को पकड़ें और अपनी बांहों को पूरी तरह फैला लें।","अपनी कोहनियों को मोड़ें और अपने शरीर को तब तक नीचे करें जब तक कि आपकी ऊपरी भुजाएं जमीन के समानांतर न हो जाएं।","एक पल के लिए रुकें, फिर अपनी हथेलियों से धक्का देकर अपनी भुजाओं को सीधा करें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0857', 'Wheel Rollerout', 'waist', 'abs', '["lower back"]', 'wheel roller', 'strength', NULL, '["Kneel on the floor and place the wheel roller in front of you.","Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.","Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.","Repeat for the desired number of repetitions."]', '["फर्श पर घुटने टेकें और व्हील रोलर को अपने सामने रखें।","अपने हाथों को व्हील रोलर के हैंडल पर रखें और अपनी बाहों को अपने सामने सीधा फैलाएं।","अपनी मुख्य मांसपेशियों को शामिल करें और अपनी पीठ सीधी और अपने पेट को टाइट रखते हुए धीरे-धीरे पहिये को आगे की ओर घुमाएँ।","जब तक आपका शरीर पूरी तरह से विस्तारित न हो जाए और आपकी भुजाएं ऊपर न आ जाएं, तब तक आगे की ओर लुढ़कना जारी रखें।","एक पल के लिए रुकें, फिर धीरे-धीरे पहिये को अपने घुटनों की ओर घुमाएँ, नियंत्रण बनाए रखें और अपने पेट को व्यस्त रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3637', 'Wheel Run', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'body weight', 'cardio', NULL, '["Start in a plank position with your hands on the wheel and your body straight.","Engage your core and start rolling the wheel forward by extending your arms.","Continue rolling until your body is fully extended and your arms are overhead.","Reverse the movement by pulling the wheel back towards your body, using your core and arms.","Repeat for the desired number of repetitions."]', '["अपने हाथों को पहिए पर और अपने शरीर को सीधा रखते हुए तख़्त स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और अपनी बाहों को फैलाकर पहिये को आगे की ओर घुमाना शुरू करें।","तब तक रोल करना जारी रखें जब तक आपका शरीर पूरी तरह से विस्तारित न हो जाए और आपकी भुजाएं ऊपर न आ जाएं।","अपने कोर और भुजाओं का उपयोग करके पहिये को अपने शरीर की ओर वापस खींचकर गति को उल्टा करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 9.8, 'time', 0, 'opengym', 1),
('og-1429', 'Wide Grip Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को आपसे दूर की ओर रखते हुए और अपने हाथों को कंधे की चौड़ाई से अधिक चौड़ा रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को एक साथ निचोड़ें।","अपने शरीर को बार की ओर ऊपर खींचें जब तक कि आपकी ठुड्डी बार के ऊपर न आ जाए।","नियंत्रण के साथ अपने शरीर को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1367', 'Wide Grip Rear Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', 'intermediate', '["Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["पुल-अप बार को चौड़ी ओवरहैंड पकड़ से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को सीधा करके बार से लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपने शरीर को अपनी छाती की ओर ले जाते हुए बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Wide-Grip_Rear_Pull-Up/0.jpg","Wide-Grip_Rear_Pull-Up/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1311', 'Wide Hand Push Up', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands wider than shoulder-width apart.","Keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से अधिक चौड़ा रखते हुए एक ऊंचे तख़्ते की स्थिति से शुरुआत करें।","अपने शरीर को सिर से पैर तक एक सीधी रेखा में रखें।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपनी छाती को ज़मीन की ओर नीचे करें।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2363', 'Wide-Grip Chest Dip On High Parallel Bars', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.","Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपनी भुजाओं को पूरी तरह फैलाकर और अपने शरीर को हवा में लटकाकर अपने आप को समानांतर सलाखों पर रखें।","थोड़ा आगे झुकें और अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे करें जब तक कि आपकी छाती सलाखों के ठीक ऊपर न आ जाए।","एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0858', 'Wind Sprints', 'waist', 'abs', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', 'beginner', '["Find an open space or a track to perform the exercise.","Start by standing with your feet shoulder-width apart.","Begin running as fast as you can, pumping your arms and driving your knees up.","Continue sprinting for a specific distance or time period.","Rest and repeat for the desired number of repetitions."]', '["व्यायाम करने के लिए एक खुली जगह या ट्रैक ढूंढें।","अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े होकर शुरुआत करें।","जितना हो सके उतनी तेजी से दौड़ना शुरू करें, अपनी बाहों को पंप करें और अपने घुटनों को ऊपर उठाएं।","एक विशिष्ट दूरी या समय अवधि तक दौड़ना जारी रखें।","आराम करें और दोहराव की वांछित संख्या के लिए दोहराएं।"]', '["Wind_Sprints/0.jpg","Wind_Sprints/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1604', 'World Greatest Stretch', 'upper legs', 'hamstrings', '["glutes","quadriceps","calves"]', 'body weight', 'strength', NULL, '["Start in a lunge position with your right foot forward and your left foot back.","Place your hands on the ground on either side of your right foot.","Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.","Rotate your torso to the right, reaching your right arm up towards the ceiling.","Hold this position for a few seconds, then return to the starting position.","Switch sides and repeat the stretch with your left foot forward."]', '["अपने दाहिने पैर को आगे और अपने बाएं पैर को पीछे रखते हुए लंज स्थिति में शुरुआत करें।","अपने हाथों को अपने दाहिने पैर के दोनों ओर जमीन पर रखें।","अपने बाएँ घुटने को ज़मीन पर टिकाएँ और अपने दाएँ पैर को फैलाएँ, अपने दाहिने पैर को ज़मीन पर सपाट रखें।","अपने धड़ को दाहिनी ओर घुमाएं, अपनी दाहिनी भुजा को छत की ओर ले जाएं।","कुछ सेकंड के लिए इस स्थिति में रहें, फिर प्रारंभिक स्थिति में लौट आएं।","करवट बदलें और अपने बाएँ पैर को आगे की ओर रखते हुए खिंचाव को दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1428', 'Wrist Circles', 'lower arms', 'forearms', '["hands","wrists"]', 'body weight', 'strength', 'beginner', '["Extend your arms straight out in front of you.","Make a fist with both hands.","Rotate your wrists in a circular motion, keeping your arms still.","Continue the wrist circles for the desired number of repetitions."]', '["अपनी बाहों को अपने सामने सीधा फैलाएं।","दोनों हाथों से मुट्ठी बांध लें.","अपनी भुजाओं को स्थिर रखते हुए अपनी कलाइयों को गोलाकार गति में घुमाएँ।","दोहराव की वांछित संख्या के लिए कलाई के घेरे जारी रखें।"]', '["Wrist_Circles/0.jpg","Wrist_Circles/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0859', 'Wrist Rollerer', 'lower arms', 'forearms', '["biceps","triceps"]', 'weighted', 'strength', NULL, '["Attach a weight to one end of a rope or bar.","Hold the other end of the rope or bar with both hands, palms facing down.","Stand with your feet shoulder-width apart and your arms fully extended in front of you.","Slowly roll the weight up towards your hands by flexing your wrists.","Pause for a moment at the top, then slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions."]', '["रस्सी या पट्टी के एक सिरे पर वजन लगाएँ।","रस्सी या पट्टी के दूसरे सिरे को दोनों हाथों से पकड़ें, हथेलियाँ नीचे की ओर।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपकी भुजाएं आपके सामने पूरी तरह फैली हुई हों।","अपनी कलाइयों को मोड़कर वजन को धीरे-धीरे अपने हाथों की ओर ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे वजन को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('fe-90_90_Hamstring', '90/90 Hamstring', 'upper legs', 'hamstrings', '["calves"]', 'body only', 'stretching', 'beginner', '["Lie on your back, with one leg extended straight out.","With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.","Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.","Repeat for 10-20 repetitions, and then switch to the other leg."]', NULL, '["90_90_Hamstring/0.jpg","90_90_Hamstring/1.jpg"]', 2.3, 'time', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Ab_Crunch_Machine', 'Ab Crunch Machine', 'waist', 'abdominals', '[]', 'machine', 'strength', 'intermediate', '["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.","At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.","After a second pause, slowly return to the starting position as you breathe in.","Repeat the movement for the prescribed amount of repetitions."]', NULL, '["Ab_Crunch_Machine/0.jpg","Ab_Crunch_Machine/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Ab_Roller', 'Ab Roller', 'waist', 'abdominals', '["shoulders"]', 'other', 'strength', 'intermediate', '["Hold the Ab Roller with both hands and kneel on the floor.","Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."]', NULL, '["Ab_Roller/0.jpg","Ab_Roller/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Adductor', 'Adductor', 'upper legs', 'adductors', '[]', 'foam roll', 'stretching', 'intermediate', '["Lie face down with one leg on a foam roll.","Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.","While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg."]', NULL, '["Adductor/0.jpg","Adductor/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Adductor_Groin', 'Adductor/Groin', 'upper legs', 'adductors', '[]', 'body only', 'stretching', 'intermediate', '["Lie on your back with your feet raised towards the ceiling.","Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.","Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.","Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury."]', NULL, '["Adductor_Groin/0.jpg","Adductor_Groin/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-All_Fours_Quad_Stretch', 'All Fours Quad Stretch', 'upper legs', 'quadriceps', '["quadriceps"]', 'body only', 'stretching', 'intermediate', '["Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.","Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.","Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides."]', NULL, '["All_Fours_Quad_Stretch/0.jpg","All_Fours_Quad_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Alternate_Hammer_Curl', 'Alternate Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. This will be your starting position.","While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."]', NULL, '["Alternate_Hammer_Curl/0.jpg","Alternate_Hammer_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Alternate_Leg_Diagonal_Bound', 'Alternate Leg Diagonal Bound', 'upper legs', 'quadriceps', '["abductors","adductors","calves","glutes","hamstrings"]', 'body only', 'plyometrics', 'beginner', '["Assume a comfortable stance with one foot slightly in front of the other.","Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.","It may help to use a line on the ground to guage distance from side to side.","Repeat the sequence with the other leg."]', NULL, '["Alternate_Leg_Diagonal_Bound/0.jpg","Alternate_Leg_Diagonal_Bound/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Alternating_Deltoid_Raise', 'Alternating Deltoid Raise', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'beginner', '["In a standing position, hold a pair of dumbbells at your side.","Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.","Return the weights to your side.","On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.","Return the weights to the starting position and continue alternating to the front and side."]', NULL, '["Alternating_Deltoid_Raise/0.jpg","Alternating_Deltoid_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Alternating_Floor_Press', 'Alternating Floor Press', 'chest', 'chest', '["abdominals","shoulders","triceps"]', 'kettlebells', 'strength', 'beginner', '["Lie on the floor with two kettlebells next to your shoulders.","Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.","Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.","Raise the kettlebell and repeat on the opposite side."]', NULL, '["Alternating_Floor_Press/0.jpg","Alternating_Floor_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Alternating_Hang_Clean', 'Alternating Hang Clean', 'upper legs', 'hamstrings', '["biceps","calves","forearms","glutes","lower back","traps"]', 'kettlebells', 'strength', 'intermediate', '["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.","Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat."]', NULL, '["Alternating_Hang_Clean/0.jpg","Alternating_Hang_Clean/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Alternating_Renegade_Row', 'Alternating Renegade Row', 'back', 'middle back', '["abdominals","biceps","chest","lats","triceps"]', 'kettlebells', 'strength', 'expert', '["Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.","Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.","Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps."]', NULL, '["Alternating_Renegade_Row/0.jpg","Alternating_Renegade_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Ankle_Circles', 'Ankle Circles', 'lower legs', 'calves', '[]', 'body only', 'stretching', 'beginner', '["Use a sturdy object like a squat rack to hold yourself.","Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.","When you are done with the right foot, then repeat with the left leg."]', NULL, '["Ankle_Circles/0.jpg","Ankle_Circles/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Ankle_On_The_Knee', 'Ankle On The Knee', 'upper legs', 'glutes', '[]', 'body only', 'stretching', 'beginner', '["From a lying position, bend your knees and keep your feet on the floor.","Place your ankle of one foot on your opposite knee.","Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides."]', NULL, '["Ankle_On_The_Knee/0.jpg","Ankle_On_The_Knee/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Anterior_Tibialis-SMR', 'Anterior Tibialis-SMR', 'lower legs', 'calves', '[]', 'other', 'stretching', 'intermediate', '["Begin seated on the ground with your legs bent and your feet on the floor.","Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg."]', NULL, '["Anterior_Tibialis-SMR/0.jpg","Anterior_Tibialis-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Anti-Gravity_Press', 'Anti-Gravity Press', 'shoulders', 'shoulders', '["middle back","traps","triceps"]', 'barbell', 'strength', 'beginner', '["Place a bar on the ground behind the head of an incline bench.","Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.","To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement.","Return to the starting position and repeat to complete the set."]', NULL, '["Anti-Gravity_Press/0.jpg","Anti-Gravity_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Arm_Circles', 'Arm Circles', 'shoulders', 'shoulders', '["traps"]', 'body only', 'stretching', 'beginner', '["Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.","Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.","Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction."]', NULL, '["Arm_Circles/0.jpg","Arm_Circles/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Around_The_Worlds', 'Around The Worlds', 'chest', 'chest', '["shoulders"]', 'dumbbell', 'strength', 'intermediate', '["Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.","Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.","Reverse the movement to return the weight to the starting position as you exhale."]', NULL, '["Around_The_Worlds/0.jpg","Around_The_Worlds/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Atlas_Stone_Trainer', 'Atlas Stone Trainer', 'back', 'lower back', '["biceps","forearms","glutes","hamstrings","quadriceps"]', 'other', 'strongman', 'intermediate', '["This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe.","Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips.","Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest.","Finish the movement by extending through your hips and knees to raise the weight as high as possible. The weight can be returned to the lap or to the ground for successive repetitions."]', NULL, '["Atlas_Stone_Trainer/0.jpg","Atlas_Stone_Trainer/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Atlas_Stones', 'Atlas Stones', 'back', 'lower back', '["abdominals","adductors","biceps","calves","forearms","glutes","hamstrings","middle back","quadriceps","traps"]', 'other', 'strongman', 'expert', '["Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.","Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.","As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.","Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible."]', NULL, '["Atlas_Stones/0.jpg","Atlas_Stones/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Axle_Deadlift', 'Axle Deadlift', 'back', 'lower back', '["forearms","glutes","hamstrings","middle back","quadriceps","traps"]', 'other', 'strongman', 'intermediate', '["Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.","With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.","After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."]', NULL, '["Axle_Deadlift/0.jpg","Axle_Deadlift/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Back_Flyes_-_With_Bands', 'Back Flyes - With Bands', 'shoulders', 'shoulders', '["middle back","triceps"]', 'bands', 'strength', 'beginner', '["Run a band around a stationary post like that of a squat rack.","Grab the band by the handles and stand back so that the tension in the band rises.","Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.","As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.","After a pause, go back to the original position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Back_Flyes_-_With_Bands/0.jpg","Back_Flyes_-_With_Bands/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Backward_Drag', 'Backward Drag', 'upper legs', 'quadriceps', '["calves","forearms","glutes","hamstrings","lower back"]', 'other', 'strongman', 'beginner', '["Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.","Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible."]', NULL, '["Backward_Drag/0.jpg","Backward_Drag/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Backward_Medicine_Ball_Throw', 'Backward Medicine Ball Throw', 'shoulders', 'shoulders', '[]', 'medicine ball', 'plyometrics', 'beginner', '["This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.","Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.","Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.","Your partner can then roll the ball back to you. Repeat for the desired number of repetitions."]', NULL, '["Backward_Medicine_Ball_Throw/0.jpg","Backward_Medicine_Ball_Throw/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Balance_Board', 'Balance Board', 'lower legs', 'calves', '["hamstrings","quadriceps"]', 'other', 'strength', 'beginner', '["Place a balance board in front of you.","Stand up on it and try to balance yourself.","Hold the balance for as long as desired."]', NULL, '["Balance_Board/0.jpg","Balance_Board/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Ball_Leg_Curl', 'Ball Leg Curl', 'upper legs', 'hamstrings', '["calves","glutes"]', 'exercise ball', 'strength', 'beginner', '["Begin on the floor laying on your back with your feet on top of the ball.","Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.","Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.","Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.","After a brief pause, return to the starting position."]', NULL, '["Ball_Leg_Curl/0.jpg","Ball_Leg_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Band_Assisted_Pull-Up', 'Band Assisted Pull-Up', 'back', 'lats', '["abdominals","forearms","middle back"]', 'other', 'strength', 'beginner', '["Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.","Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.","Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.","After a brief pause, return to the starting position."]', NULL, '["Band_Assisted_Pull-Up/0.jpg","Band_Assisted_Pull-Up/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Band_Good_Morning', 'Band Good Morning', 'upper legs', 'hamstrings', '["glutes","lower back"]', 'bands', 'powerlifting', 'beginner', '["Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.","Keeping your legs straight, extend through the hips to come to a near vertical position.","Ensure that you do not round your back as you go down back to the starting position."]', NULL, '["Band_Good_Morning/0.jpg","Band_Good_Morning/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Band_Good_Morning_Pull_Through', 'Band Good Morning (Pull Through)', 'upper legs', 'hamstrings', '["glutes","lower back"]', 'bands', 'powerlifting', 'beginner', '["Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.","Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.","Return to the starting position be driving through with the hips to come back to a standing position."]', NULL, '["Band_Good_Morning_Pull_Through/0.jpg","Band_Good_Morning_Pull_Through/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Band_Hip_Adductions', 'Band Hip Adductions', 'upper legs', 'adductors', '[]', 'bands', 'strength', 'beginner', '["Anchor a band around a solid post or other object.","Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.","Stand up straight and hold onto the post if needed. This will be your starting position.","Keeping the knee straight, raise your right legs out to the side as far as you can.","Return to the starting position and repeat for the desired rep count.","Switch sides."]', NULL, '["Band_Hip_Adductions/0.jpg","Band_Hip_Adductions/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Band_Pull_Apart', 'Band Pull Apart', 'shoulders', 'shoulders', '["middle back","traps"]', 'bands', 'strength', 'beginner', '["Begin with your arms extended straight out in front of you, holding the band with both hands.","Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.","Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.","Pause as you complete the movement, returning to the starting position under control."]', NULL, '["Band_Pull_Apart/0.jpg","Band_Pull_Apart/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Band_Skull_Crusher', 'Band Skull Crusher', 'upper arms', 'triceps', '[]', 'bands', 'strength', 'beginner', '["Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.","Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.","Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position."]', NULL, '["Band_Skull_Crusher/0.jpg","Band_Skull_Crusher/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Barbell_Ab_Rollout', 'Barbell Ab Rollout', 'waist', 'abdominals', '["lower back","shoulders"]', 'barbell', 'strength', 'intermediate', '["For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.","While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.","After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Barbell_Ab_Rollout/0.jpg","Barbell_Ab_Rollout/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Barbell_Ab_Rollout_-_On_Knees', 'Barbell Ab Rollout - On Knees', 'waist', 'abdominals', '["lower back","shoulders"]', 'barbell', 'strength', 'expert', '["Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.","Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."]', NULL, '["Barbell_Ab_Rollout_-_On_Knees/0.jpg","Barbell_Ab_Rollout_-_On_Knees/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Barbell_Curls_Lying_Against_An_Incline', 'Barbell Curls Lying Against An Incline', 'upper arms', 'biceps', '[]', 'barbell', 'strength', 'beginner', '["Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.","While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.","After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.","Repeat for the recommended amount of repetitions."]', NULL, '["Barbell_Curls_Lying_Against_An_Incline/0.jpg","Barbell_Curls_Lying_Against_An_Incline/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Barbell_Hip_Thrust', 'Barbell Hip Thrust', 'upper legs', 'glutes', '["calves","hamstrings"]', 'barbell', 'powerlifting', 'intermediate', '["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.","Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.","Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."]', NULL, '["Barbell_Hip_Thrust/0.jpg","Barbell_Hip_Thrust/1.jpg"]', 6, 'sets', 1, 'fedb', 1),
('fe-Barbell_Rollout_from_Bench', 'Barbell Rollout from Bench', 'waist', 'abdominals', '["glutes","hamstrings","lats","shoulders"]', 'barbell', 'strength', 'intermediate', '["Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.","To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.","When the bar has been moved as far forward as possible, return to the starting position."]', NULL, '["Barbell_Rollout_from_Bench/0.jpg","Barbell_Rollout_from_Bench/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Barbell_Shoulder_Press', 'Barbell Shoulder Press', 'shoulders', 'shoulders', '["chest","triceps"]', 'barbell', 'strength', 'intermediate', '["Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).","Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the shoulders slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Barbell_Shoulder_Press/0.jpg","Barbell_Shoulder_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Barbell_Shrug_Behind_The_Back', 'Barbell Shrug Behind The Back', 'back', 'traps', '["forearms","middle back"]', 'barbell', 'strength', 'beginner', '["Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.","Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."]', NULL, '["Barbell_Shrug_Behind_The_Back/0.jpg","Barbell_Shrug_Behind_The_Back/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Barbell_Side_Bend', 'Barbell Side Bend', 'waist', 'abdominals', '["lower back"]', 'barbell', 'strength', 'beginner', '["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Barbell_Side_Bend/0.jpg","Barbell_Side_Bend/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Barbell_Squat', 'Barbell Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","lower back"]', 'barbell', 'strength', 'beginner', '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Barbell_Squat/0.jpg","Barbell_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Barbell_Walking_Lunge', 'Barbell Walking Lunge', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'barbell', 'strength', 'beginner', '["Begin standing with your feet shoulder width apart and a barbell across your upper back.","Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."]', NULL, '["Barbell_Walking_Lunge/0.jpg","Barbell_Walking_Lunge/1.jpg"]', 3.5, 'sets', 0, 'fedb', 1),
('fe-Battling_Ropes', 'Battling Ropes', 'shoulders', 'shoulders', '["chest","forearms"]', 'other', 'strength', 'beginner', '["For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.","Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.","As you let that arm drop to the starting position, raise the opposite side.","Continue alternating your left and right arms, whipping the ropes up and down as fast as you can."]', NULL, '["Battling_Ropes/0.jpg","Battling_Ropes/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bear_Crawl_Sled_Drags', 'Bear Crawl Sled Drags', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'other', 'strongman', 'beginner', '["Wearing either a harness or a loose weight belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that your hands are on the ground. Your back should be flat and knees bent. This is your starting position.","Begin by driving with legs, alternating left and right. Use your hands to maintain balance and to help pull. Try to keep your back flat as you move over a given distance."]', NULL, '["Bear_Crawl_Sled_Drags/0.jpg","Bear_Crawl_Sled_Drags/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Behind_Head_Chest_Stretch', 'Behind Head Chest Stretch', 'chest', 'chest', '["shoulders"]', 'other', 'stretching', 'expert', '["Sit upright on the floor with your partner behind you.","Place your hands behind your hand, and push your elbows back as far as you can. Your partner should hold your elbows. This will be your starting position.","Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds. Your partner should prevent your elbows from moving.","Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury."]', NULL, '["Behind_Head_Chest_Stretch/0.jpg","Behind_Head_Chest_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Bench_Dips', 'Bench Dips', 'upper arms', 'triceps', '["chest","shoulders"]', 'body only', 'strength', 'beginner', '["For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.","Using your triceps to bring your torso up again, lift yourself back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Bench_Dips/0.jpg","Bench_Dips/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bench_Jump', 'Bench Jump', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'body only', 'plyometrics', 'intermediate', '["Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.","Perform a short squat in preparation for the jump; swing your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Jump over the bench, landing with the knees bent, absorbing the impact through the legs.","Turn around and face the opposite direction, then jump back over the bench."]', NULL, '["Bench_Jump/0.jpg","Bench_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Bench_Press_-_Powerlifting', 'Bench Press - Powerlifting', 'upper arms', 'triceps', '["chest","forearms","lats","shoulders"]', 'barbell', 'powerlifting', 'intermediate', '["Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.","Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."]', NULL, '["Bench_Press_-_Powerlifting/0.jpg","Bench_Press_-_Powerlifting/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Bench_Press_with_Chains', 'Bench Press with Chains', 'upper arms', 'triceps', '["chest","lats","shoulders"]', 'barbell', 'powerlifting', 'expert', '["Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.","Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.","Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."]', NULL, '["Bench_Press_with_Chains/0.jpg","Bench_Press_with_Chains/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Bench_Sprint', 'Bench Sprint', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'other', 'plyometrics', 'beginner', '["Stand on the ground with one foot resting on a bench or box with your heel close to the edge.","Push off with your foot on top of the bench, extending through the hip and knee.","Land with the opposite foot on top of the box, returning your other foot back to the start position.","Continue alternating from one foot to another to complete the set."]', NULL, '["Bench_Sprint/0.jpg","Bench_Sprint/1.jpg"]', 9.8, 'sets', 0, 'fedb', 1),
('fe-Bent-Arm_Dumbbell_Pullover', 'Bent-Arm Dumbbell Pullover', 'chest', 'chest', '["lats","shoulders","triceps"]', 'dumbbell', 'strength', 'intermediate', '["Place a dumbbell standing up on a flat bench.","Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.","Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.","While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."]', NULL, '["Bent-Arm_Dumbbell_Pullover/0.jpg","Bent-Arm_Dumbbell_Pullover/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench', 'Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'beginner', '["Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.","While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.","Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.","After a one second contraction at the top, slowly lower the dumbbells back to the starting position.","Repeat the recommended amount of repetitions."]', NULL, '["Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg","Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bent_Over_Low-Pulley_Side_Lateral', 'Bent Over Low-Pulley Side Lateral', 'shoulders', 'shoulders', '["lower back","middle back","traps"]', 'cable', 'strength', 'beginner', '["Select a weight and hold the handle of the low pulley with your right hand.","Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.","Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.","Slowly lower the weight back to the starting position as you breathe in.","Repeat for the recommended amount of repetitions and repeat the movement with the other arm."]', NULL, '["Bent_Over_Low-Pulley_Side_Lateral/0.jpg","Bent_Over_Low-Pulley_Side_Lateral/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bent_Over_One-Arm_Long_Bar_Row', 'Bent Over One-Arm Long Bar Row', 'back', 'middle back', '["biceps","lats","lower back","traps"]', 'barbell', 'strength', 'beginner', '["Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.","Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.","Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.","Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.","Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).","Repeat for the recommended amount of repetitions and switch arms."]', NULL, '["Bent_Over_One-Arm_Long_Bar_Row/0.jpg","Bent_Over_One-Arm_Long_Bar_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bent_Over_Two-Arm_Long_Bar_Row', 'Bent Over Two-Arm Long Bar Row', 'back', 'middle back', '["biceps","lats"]', 'barbell', 'strength', 'intermediate', '["Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.","Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.","Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.","Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Use a stirrup or double handle cable attachment by hooking it under the end of the bar.","Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).","Repeat for the recommended amount of repetitions."]', NULL, '["Bent_Over_Two-Arm_Long_Bar_Row/0.jpg","Bent_Over_Two-Arm_Long_Bar_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bent_Over_Two-Dumbbell_Row', 'Bent Over Two-Dumbbell Row', 'back', 'middle back', '["biceps","lats","shoulders"]', 'dumbbell', 'strength', 'beginner', '["With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Bent_Over_Two-Dumbbell_Row/0.jpg","Bent_Over_Two-Dumbbell_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bent_Over_Two-Dumbbell_Row_With_Palms_In', 'Bent Over Two-Dumbbell Row With Palms In', 'back', 'middle back', '["biceps","lats"]', 'dumbbell', 'strength', 'beginner', '["With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg","Bent_Over_Two-Dumbbell_Row_With_Palms_In/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bent_Press', 'Bent Press', 'waist', 'abdominals', '["glutes","hamstrings","lower back","quadriceps","shoulders","triceps"]', 'kettlebells', 'strength', 'expert', '["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.","Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.","Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions."]', NULL, '["Bent_Press/0.jpg","Bent_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bicycling', 'Bicycling', 'cardio', 'quadriceps', '["calves","glutes","hamstrings"]', 'other', 'cardio', 'beginner', '["To begin, seat yourself on the bike and adjust the seat to your height."]', NULL, '["Bicycling/0.jpg","Bicycling/1.jpg"]', 7.5, 'time', 0, 'fedb', 1),
('fe-Bicycling_Stationary', 'Bicycling, Stationary', 'cardio', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'cardio', 'beginner', '["To begin, seat yourself on the bike and adjust the seat to your height.","Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity."]', NULL, '["Bicycling_Stationary/0.jpg","Bicycling_Stationary/1.jpg"]', 7.5, 'time', 0, 'fedb', 1),
('fe-Board_Press', 'Board Press', 'upper arms', 'triceps', '["chest","forearms","lats","shoulders"]', 'barbell', 'powerlifting', 'intermediate', '["Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.","Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.","Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."]', NULL, '["Board_Press/0.jpg","Board_Press/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Body_Tricep_Press', 'Body Tricep Press', 'upper arms', 'triceps', '[]', 'body only', 'strength', 'beginner', '["Position a bar in a rack at chest height.","Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.","Begin by flexing the elbow, lowering yourself towards the bar.","Pause, and then reverse the motion by extending the elbows.","Progress from bodyweight by adding chains over your shoulders."]', NULL, '["Body_Tricep_Press/0.jpg","Body_Tricep_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bodyweight_Flyes', 'Bodyweight Flyes', 'chest', 'chest', '["abdominals","shoulders","triceps"]', 'e-z curl bar', 'strength', 'intermediate', '["Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.","Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.","Place your hands on the bars. This will be your starting position.","Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.","After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement."]', NULL, '["Bodyweight_Flyes/0.jpg","Bodyweight_Flyes/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bodyweight_Mid_Row', 'Bodyweight Mid Row', 'back', 'middle back', '["biceps","lats"]', 'other', 'strength', 'intermediate', '["Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.","Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.","After a brief pause, return to the starting position."]', NULL, '["Bodyweight_Mid_Row/0.jpg","Bodyweight_Mid_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bodyweight_Squat', 'Bodyweight Squat', 'upper legs', 'quadriceps', '["glutes","hamstrings"]', 'body only', 'strength', 'beginner', '["Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."]', NULL, '["Bodyweight_Squat/0.jpg","Bodyweight_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Bodyweight_Walking_Lunge', 'Bodyweight Walking Lunge', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'body only', 'strength', 'beginner', '["Begin standing with your feet shoulder width apart and your hands on your hips.","Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."]', NULL, '["Bodyweight_Walking_Lunge/0.jpg","Bodyweight_Walking_Lunge/1.jpg"]', 3.5, 'sets', 0, 'fedb', 1),
('fe-Bottoms-Up_Clean_From_The_Hang_Position', 'Bottoms-Up Clean From The Hang Position', 'lower arms', 'forearms', '["biceps","shoulders"]', 'kettlebells', 'strength', 'intermediate', '["Initiate the exercise by standing upright with a kettlebell in one hand.","Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder."]', NULL, '["Bottoms-Up_Clean_From_The_Hang_Position/0.jpg","Bottoms-Up_Clean_From_The_Hang_Position/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Box_Jump_Multiple_Response', 'Box Jump (Multiple Response)', 'upper legs', 'hamstrings', '["abductors","adductors","calves","glutes","quadriceps"]', 'other', 'plyometrics', 'beginner', '["Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent.","Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.","Immediately drop or jump back down to the original starting place; then repeat the sequence."]', NULL, '["Box_Jump_Multiple_Response/0.jpg","Box_Jump_Multiple_Response/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Box_Skip', 'Box Skip', 'upper legs', 'hamstrings', '["abductors","adductors","calves","glutes","quadriceps"]', 'other', 'plyometrics', 'beginner', '["You will need several boxes lined up about 8 feet apart.","Begin facing the first box with one leg slightly behind the other.","Drive off the back leg, attempting to gain as much height with the hips as possible.","Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.","Then, step to the next box and repeat."]', NULL, '["Box_Skip/0.jpg","Box_Skip/1.jpg"]', 11, 'sets', 0, 'fedb', 1),
('fe-Box_Squat', 'Box Squat', 'upper legs', 'quadriceps', '["adductors","calves","glutes","hamstrings","lower back"]', 'barbell', 'powerlifting', 'intermediate', '["The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe."]', NULL, '["Box_Squat/0.jpg","Box_Squat/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Box_Squat_with_Bands', 'Box Squat with Bands', 'upper legs', 'quadriceps', '["abductors","adductors","calves","glutes","hamstrings","lower back"]', 'barbell', 'powerlifting', 'expert', '["Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don''t move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack."]', NULL, '["Box_Squat_with_Bands/0.jpg","Box_Squat_with_Bands/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Box_Squat_with_Chains', 'Box Squat with Chains', 'upper legs', 'quadriceps', '["abductors","adductors","calves","glutes","hamstrings","lower back"]', 'barbell', 'strength', 'expert', '["Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe."]', NULL, '["Box_Squat_with_Chains/0.jpg","Box_Squat_with_Chains/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Brachialis-SMR', 'Brachialis-SMR', 'upper arms', 'biceps', '[]', 'foam roll', 'stretching', 'intermediate', '["Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.","Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides."]', NULL, '["Brachialis-SMR/0.jpg","Brachialis-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Bradford_Rocky_Presses', 'Bradford/Rocky Presses', 'shoulders', 'shoulders', '["triceps"]', 'barbell', 'strength', 'beginner', '["Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position.","Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms.","Now lower the bar down to the back of the head slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Lower the bar down to the starting position slowly as you inhale. This is one repetition.","Alternate in this manner until you complete the recommended amount of repetitions."]', NULL, '["Bradford_Rocky_Presses/0.jpg","Bradford_Rocky_Presses/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Butt_Lift_Bridge', 'Butt Lift (Bridge)', 'upper legs', 'glutes', '["hamstrings"]', 'body only', 'strength', 'beginner', '["Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.","Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.","Slowly go back to the starting position as you breathe in."]', NULL, '["Butt_Lift_Bridge/0.jpg","Butt_Lift_Bridge/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Butterfly', 'Butterfly', 'chest', 'chest', '[]', 'machine', 'strength', 'beginner', '["Sit on the machine with your back flat on the pad.","Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.","Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.","Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.","Repeat for the recommended amount of repetitions."]', NULL, '["Butterfly/0.jpg","Butterfly/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Cable_Chest_Press', 'Cable Chest Press', 'chest', 'chest', '["shoulders","triceps"]', 'cable', 'strength', 'beginner', '["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.","After pausing at full extension, return to th starting position, keeping tension on the cables.","You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands."]', NULL, '["Cable_Chest_Press/0.jpg","Cable_Chest_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_Crossover', 'Cable Crossover', 'chest', 'chest', '["shoulders"]', 'cable', 'strength', 'beginner', '["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.","Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."]', NULL, '["Cable_Crossover/0.jpg","Cable_Crossover/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_Crunch', 'Cable Crunch', 'waist', 'abdominals', '[]', 'cable', 'strength', 'beginner', '["Kneel below a high pulley that contains a rope attachment.","Grasp cable rope attachment and lower the rope until your hands are placed next to your face.","Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.","With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.","Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.","Repeat for the recommended amount of repetitions."]', NULL, '["Cable_Crunch/0.jpg","Cable_Crunch/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_Hammer_Curls_-_Rope_Attachment', 'Cable Hammer Curls - Rope Attachment', 'upper arms', 'biceps', '[]', 'cable', 'strength', 'beginner', '["Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.","Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.","Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.","Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.","After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.","Repeat for the recommended amount of repetitions."]', NULL, '["Cable_Hammer_Curls_-_Rope_Attachment/0.jpg","Cable_Hammer_Curls_-_Rope_Attachment/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_Internal_Rotation', 'Cable Internal Rotation', 'shoulders', 'shoulders', '[]', 'cable', 'strength', 'beginner', '["Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead.","Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.","Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times.","Slowly go back to the initial position.","Repeat for the recommended amount of repetitions and then repeat the movement with the next arm."]', NULL, '["Cable_Internal_Rotation/0.jpg","Cable_Internal_Rotation/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_Iron_Cross', 'Cable Iron Cross', 'chest', 'chest', '[]', 'cable', 'strength', 'beginner', '["Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.","Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a \"T\". This will be your starting position.","Keeping the elbows extended, pull your arms straight to your sides.","Return your arms back to the starting position after a pause at the peak contraction.","Continue the movement for the prescribed number of repetitions."]', NULL, '["Cable_Iron_Cross/0.jpg","Cable_Iron_Cross/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_Lying_Triceps_Extension', 'Cable Lying Triceps Extension', 'upper arms', 'triceps', '[]', 'cable', 'strength', 'beginner', '["Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.","With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.","Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.","Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.","Hold for a second at the contracted position and repeat for the recommended amount of repetitions."]', NULL, '["Cable_Lying_Triceps_Extension/0.jpg","Cable_Lying_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_One_Arm_Tricep_Extension', 'Cable One Arm Tricep Extension', 'upper arms', 'triceps', '[]', 'cable', 'strength', 'beginner', '["With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.","Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.","As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.","Squeeze the triceps and hold for a second in this contracted position.","Slowly return the handle to the starting position.","Repeat for the recommended amount of repetitions and then perform the same movement with the other arm."]', NULL, '["Cable_One_Arm_Tricep_Extension/0.jpg","Cable_One_Arm_Tricep_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_Rear_Delt_Fly', 'Cable Rear Delt Fly', 'shoulders', 'shoulders', '[]', 'cable', 'strength', 'beginner', '["Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.","Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.","Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.","Pause at the end of the motion before returning the handles to the start position."]', NULL, '["Cable_Rear_Delt_Fly/0.jpg","Cable_Rear_Delt_Fly/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_Rope_Overhead_Triceps_Extension', 'Cable Rope Overhead Triceps Extension', 'upper arms', 'triceps', '[]', 'cable', 'strength', 'beginner', '["Attach a rope to the bottom pulley of the pulley machine.","Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.","Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out.","Repeat for the recommended amount of repetitions."]', NULL, '["Cable_Rope_Overhead_Triceps_Extension/0.jpg","Cable_Rope_Overhead_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_Russian_Twists', 'Cable Russian Twists', 'waist', 'abdominals', '[]', 'cable', 'strength', 'beginner', '["Connect a standard handle attachment, and position the cable to a middle pulley position.","Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.","Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.","Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.","Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.","Repeat the same movement to failure.","Then, reposition and repeat the same series of movements on the opposite side."]', NULL, '["Cable_Russian_Twists/0.jpg","Cable_Russian_Twists/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_Seated_Lateral_Raise', 'Cable Seated Lateral Raise', 'shoulders', 'shoulders', '["middle back","traps"]', 'cable', 'strength', 'beginner', '["Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.","Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.","Bend forward while keeping your back flat and rest your torso on the thighs.","Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.","While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.","Slowly lower your arms to the starting position as you inhale.","Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise."]', NULL, '["Cable_Seated_Lateral_Raise/0.jpg","Cable_Seated_Lateral_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cable_Shoulder_Press', 'Cable Shoulder Press', 'shoulders', 'shoulders', '["triceps"]', 'cable', 'strength', 'beginner', '["Move the cables to the bottom of the towers and select an appropriate weight.","Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.","Keeping your head and chest up, extend through the elbow to press the handles directly over head.","After pausing at the top, return to the starting position and repeat."]', NULL, '["Cable_Shoulder_Press/0.jpg","Cable_Shoulder_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Calf-Machine_Shoulder_Shrug', 'Calf-Machine Shoulder Shrug', 'back', 'traps', '[]', 'machine', 'strength', 'beginner', '["Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.","Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.","Slowly return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Calf-Machine_Shoulder_Shrug/0.jpg","Calf-Machine_Shoulder_Shrug/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Calf_Press', 'Calf Press', 'lower legs', 'calves', '[]', 'machine', 'strength', 'beginner', '["Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.","Select an appropriate weight, and grasp the handles. This will be your starting position.","Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible.","After a brief pause, reverse the motion and repeat."]', NULL, '["Calf_Press/0.jpg","Calf_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Calf_Press_On_The_Leg_Press_Machine', 'Calf Press On The Leg Press Machine', 'lower legs', 'calves', '[]', 'machine', 'strength', 'beginner', '["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."]', NULL, '["Calf_Press_On_The_Leg_Press_Machine/0.jpg","Calf_Press_On_The_Leg_Press_Machine/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Calf_Raise_On_A_Dumbbell', 'Calf Raise On A Dumbbell', 'lower legs', 'calves', '[]', 'dumbbell', 'strength', 'intermediate', '["Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.","Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.","Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward.","Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.","Repeat for the recommended amount of repetitions."]', NULL, '["Calf_Raise_On_A_Dumbbell/0.jpg","Calf_Raise_On_A_Dumbbell/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Calf_Raises_-_With_Bands', 'Calf Raises - With Bands', 'lower legs', 'calves', '[]', 'bands', 'strength', 'beginner', '["Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.","While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.","Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.","After a one second contraction, slowly go back down to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Calf_Raises_-_With_Bands/0.jpg","Calf_Raises_-_With_Bands/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Calf_Stretch_Elbows_Against_Wall', 'Calf Stretch Elbows Against Wall', 'lower legs', 'calves', '[]', 'body only', 'stretching', 'beginner', '["Stand facing a wall from a couple feet away.","Lean against the wall, placing your weight on your forearms.","Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively."]', NULL, '["Calf_Stretch_Elbows_Against_Wall/0.jpg","Calf_Stretch_Elbows_Against_Wall/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Calf_Stretch_Hands_Against_Wall', 'Calf Stretch Hands Against Wall', 'lower legs', 'calves', '[]', 'body only', 'stretching', 'beginner', '["Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.","Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.","Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides."]', NULL, '["Calf_Stretch_Hands_Against_Wall/0.jpg","Calf_Stretch_Hands_Against_Wall/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Calves-SMR', 'Calves-SMR', 'lower legs', 'calves', '[]', 'foam roll', 'stretching', 'intermediate', '["Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.","Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg."]', NULL, '["Calves-SMR/0.jpg","Calves-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Car_Deadlift', 'Car Deadlift', 'upper legs', 'quadriceps', '["forearms","glutes","hamstrings","lower back","traps"]', 'other', 'strongman', 'intermediate', '["This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs.","Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With your feet and your grip set, take a big breath and then lower your hips and flex the knees.","Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.","Lower the weight by bending at the hips and guiding it to the floor."]', NULL, '["Car_Deadlift/0.jpg","Car_Deadlift/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Car_Drivers', 'Car Drivers', 'shoulders', 'shoulders', '["forearms"]', 'barbell', 'strength', 'beginner', '["While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.","Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.","Reverse the motion, turning it all the way to the opposite side.","Repeat for the recommended amount of repetitions."]', NULL, '["Car_Drivers/0.jpg","Car_Drivers/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Carioca_Quick_Step', 'Carioca Quick Step', 'upper legs', 'adductors', '["abdominals","abductors","calves","glutes","hamstrings","quadriceps"]', 'body only', 'plyometrics', 'beginner', '["Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.","With your right foot, quick step behind and pull the knee up.","Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side."]', NULL, '["Carioca_Quick_Step/0.jpg","Carioca_Quick_Step/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Cat_Stretch', 'Cat Stretch', 'back', 'lower back', '["middle back","traps"]', 'body only', 'stretching', 'beginner', '["Position yourself on the floor on your hands and knees.","Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.","Hold for 15 seconds."]', NULL, '["Cat_Stretch/0.jpg","Cat_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1)
